/** All translations for zizhitongjian ch.030 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起屠維赤奮若，盡著雍閹茂，凡十年。", literal: "From Tuyu Chifenruo through Zhuyong Yanmao; ten years in all.", idiomatic: "From Tuyu Chifenruo through Zhuyong Yanmao—ten years in all." },
  { zh: "1　春，正月，乙丑，悼考廟災。", literal: "1. In spring, the first month, on yichou, the memorial temple of Emperor Daokao burned.", idiomatic: "1. In spring, the first month, on yichou, the memorial temple of Emperor Daokao burned." },
  { zh: "----2　石顯遷長信中太僕，秩中二千石。", literal: "----2 Shi Xian was transferred to Grand Steward of Changxin Palace at rank of two thousand shi.", idiomatic: "----2 Shi Xian was transferred to Grand Steward of Changxin Palace at rank of two thousand shi." },
  { zh: "顯旣失倚，離權，於是丞相、御史條奏顯舊惡；", literal: "Once Xian had lost his support and separated from power, the Chancellor and Censor-in-Chief itemized memorials on Xian's old crimes;", idiomatic: "Once Xian had lost his patron and been stripped of power, the Chancellor and Censor-in-Chief itemized memorials on his old crimes;" },
  { zh: "及其黨牢梁、陳順皆免官，顯與妻子徙歸故郡，憂懣不食，道死。", literal: "and his clique Lao Liang and Chen Shun were all dismissed from office; Xian, with wife and children, was banished to his home commandery, distressed and refusing food, and died on the road.", idiomatic: "and his clique Lao Liang and Chen Shun were all dismissed; Xian, with wife and children, was banished to his home commandery, anguished and refusing food, and died on the road." },
  { zh: "諸所交結以顯爲官者，皆廢罷；", literal: "All who had bonded with Xian to obtain office were demoted and dismissed;", idiomatic: "All who had curried favor with Xian to obtain office were demoted and dismissed;" },
  { zh: "少府五鹿充宗左遷玄菟太守，御史中丞伊嘉為鴈門都尉。", literal: "Grandee of War Service Wulu Chongzong was demoted to Administrator of Xuantu; Vice Censor-in-Chief Yi Jia became Commandant of Yanmen.", idiomatic: "Grandee of War Service Wulu Chongzong was demoted to Administrator of Xuantu; Vice Censor-in-Chief Yi Jia became Commandant of Yanmen." },
  { zh: "司隸校尉涿郡王尊劾奏：「丞相衡、御史大夫譚，知顯等顓權擅勢，大作威福，爲海內患害，不以時白奏行罰；", literal: "Metropolitan Commandant Wang Zun of Zhuo commandery impeached: \"Chancellor Heng and Censor-in-Chief Tan knew that Xian and others monopolized power and arrogated momentum, greatly made authority and favor, became harm to the realm, yet did not promptly report and memorialize to carry out punishment;", idiomatic: "Metropolitan Commandant Wang Zun of Zhuo commandery impeached: \"Chancellor Heng and Censor-in-Chief Tan knew that Xian and others monopolized power and abused their position, made great show of authority and favor, and became a scourge within the seas, yet did not promptly report and seek punishment;" },
  { zh: "而阿諛曲從，附下罔上，懷邪迷國，無大臣輔政之義，皆不道！", literal: "but fawned and bent to follow, attached to those below and deceived those above, harbored depravity and misled the state, lacked the meaning of great ministers assisting government—all unfilial to the Way!", idiomatic: "but fawned and bent to their will, sided with inferiors and deceived superiors, harbored depravity and misled the state, and failed in the duty of great ministers who assist government—all crimes against the Way!" },
  { zh: "在赦令前。", literal: "[The offense was] before the amnesty edict.", idiomatic: "[The offense was] before the amnesty edict." },
  { zh: "赦後，衡、譚舉奏顯，不自陳不忠之罪，而反揚著先帝任用傾覆之徒，妄言『百官畏之，甚於主上』；", literal: "After the amnesty, Heng and Tan memorialized against Xian, did not themselves confess the crime of disloyalty, but on the contrary publicized how the former emperor had employed overturning men, recklessly saying \"the hundred officials fear him more than they fear their lord\";", idiomatic: "After the amnesty, Heng and Tan memorialized against Xian, did not confess their own disloyalty, but on the contrary publicized how the former emperor had employed men who overturned the state, recklessly saying \"the hundred officials fear him more than they fear their lord\";" },
  { zh: "卑君尊臣，非所宜稱，失大臣體！", literal: "degrading the ruler and honoring ministers—not what should be said, losing the deportment of great ministers!", idiomatic: "degrading the ruler and honoring ministers—not what should be said, and unworthy of great ministers!" },
  { zh: "於是衡慙懼，免冠謝罪，上丞相、侯印綬。", literal: "Thereupon Heng was ashamed and afraid, removed his cap and apologized for his crime, and submitted the Chancellor's seal and cord and marquis seal and cord.", idiomatic: "Thereupon Heng was ashamed and afraid, removed his cap and apologized, and submitted the Chancellor's seal and cord and his marquis seal and cord." },
  { zh: "天子以新卽位，重傷大臣，乃左遷尊爲高陵令。", literal: "The Son of Heaven, because he had newly succeeded the throne and deeply grieved to harm great ministers, demoted Zun to Magistrate of Gaoling.", idiomatic: "The emperor, having newly succeeded the throne and loath to harm great ministers, demoted Zun to Magistrate of Gaoling." },
  { zh: "然羣下多是尊者。", literal: "Yet those below mostly sided with Zun.", idiomatic: "Yet most at court sided with Zun." },
  { zh: "衡嘿嘿不自安，每有水旱，連乞骸骨讓位；", literal: "Heng mutely was not at ease; whenever there was flood or drought, he repeatedly begged his old bones and yielded his position;", idiomatic: "Heng fell silent and ill at ease; whenever flood or drought struck, he repeatedly begged to resign and yield his post;" },
  { zh: "上輒以詔書慰撫，不許。", literal: "the emperor then with edict comforted and soothed him, not permitting it.", idiomatic: "the emperor each time comforted him by edict and would not permit it." },
  { zh: "----3　立故河間王元弟上郡庫令良為河間王。", literal: "----3 The younger brother of the former King Yuan of Hejian, Liang, Commandant of the Granary of Shang commandery, was established as King of Hejian.", idiomatic: "----3 Liang, younger brother of the former King Yuan of Hejian and Commandant of the Granary of Shang commandery, was established as King of Hejian." },
  { zh: "----4　有星孛于營室。", literal: "----4 A broom star appeared in Camp Palace.", idiomatic: "----4 A broom star appeared in Camp Palace." },
  { zh: "----5　赦天下。", literal: "----5 A general amnesty was proclaimed.", idiomatic: "----5 The empire was pardoned." },
  { zh: "----6　壬子，封舅諸吏、光祿大夫、關內侯王崇爲安成侯；", literal: "----6 On renzi, the maternal uncle Clerk of Various Offices, Household Grandee, Marquis Within the Passes Wang Chong was enfeoffed as Marquis of Ancheng;", idiomatic: "----6 On renzi, the maternal uncle Wang Chong—Clerk of Various Offices, Household Grandee, Marquis Within the Passes—was enfeoffed as Marquis of Ancheng;" },
  { zh: "賜舅譚、商、立、根、逢時爵關內侯。", literal: "maternal uncles Tan, Shang, Li, Gen, and Fengshi were granted the rank Marquis Within the Passes.", idiomatic: "maternal uncles Tan, Shang, Li, Gen, and Fengshi were granted the rank Marquis Within the Passes." },
  { zh: "夏，四月，黃霧四塞，詔博問公卿大夫，無有所諱。", literal: "In summer, the fourth month, yellow mist blocked on all four sides; an edict broadly questioned dukes, ministers, and grandees, with nothing tabooed.", idiomatic: "In summer, the fourth month, yellow mist closed in on all sides; an edict ordered a broad inquiry of dukes, ministers, and grandees, with nothing held back." },
  { zh: "諫大夫楊興、博士駟勝等皆以為「陰盛侵陽之氣也。", literal: "Remonstrance Grandee Yang Xing, Erudite Si Sheng, and others all considered it \"qi of yin in excess invading yang.", idiomatic: "Remonstrance Grandee Yang Xing, Erudite Si Sheng, and others all held that it was \"the qi of excessive yin invading yang." },
  { zh: "高祖之約，非功臣不侯；", literal: "The Founder's covenant: without being a meritorious minister, one is not enfeoffed as marquis;", idiomatic: "The Founder's covenant: without merit, no marquisate;" },
  { zh: "今太后諸弟皆以無功爲侯，外戚未曾有也，故天為見異。", literal: "now the Empress Dowager's younger brothers all were made marquises without merit—consort kin have never had this—hence Heaven made a manifestation of anomaly.", idiomatic: "now the Empress Dowager's younger brothers have all been made marquises without merit—consort kin have never had this—hence Heaven has shown an omen." },
  { zh: "」於是大將軍鳳懼，上書乞骸骨，辭職；", literal: "\" Thereupon Grand General-in-Chief Feng was afraid, submitted a memorial begging his old bones and resigning his office;", idiomatic: "\" Thereupon Grand General-in-Chief Feng was afraid, submitted a memorial begging to resign and yield his post;" },
  { zh: "上優詔不許。", literal: "the emperor with a gracious edict did not permit it.", idiomatic: "the emperor replied with a gracious edict and would not permit it." },
  { zh: "----7　御史中丞東海薛宣上疏曰：「陛下至德仁厚，而嘉氣尚凝，陰陽不和，殆吏多苛政。", literal: "----7 Vice Censor-in-Chief Xue Xuan of Donghai submitted a memorial saying: \"Your Majesty's utmost virtue is benevolent and thick, yet auspicious qi is still congealed, yin and yang are not harmonized—perhaps because clerks have many harsh policies.", idiomatic: "----7 Vice Censor-in-Chief Xue Xuan of Donghai submitted a memorial saying: \"Your Majesty's virtue is supremely benevolent and generous, yet auspicious qi remains congealed and yin and yang are not in harmony—perhaps because officials enforce too many harsh policies." },
  { zh: "部刺史或不循守條職，舉錯各以其意，多與郡縣事，至開私門，聽讒佞，以求吏民過，譴呵及細微，責義不量力；", literal: "Regional Inspectors sometimes do not follow and keep to their statutory duties; promotions and demotions each follow their private intent, they much interfere in commandery and county affairs, even opening private gates, listening to slanderous flatterers, to seek the faults of clerks and commoners, rebuking and scolding down to minutiae, demanding righteousness beyond their strength;", idiomatic: "Regional Inspectors sometimes neglect their statutory duties, promote and demote by private whim, meddle heavily in commandery and county affairs, even open their doors to slanderers and flatterers to hunt out petty faults among officials and people, rebuke trifles, and demand righteousness beyond anyone's strength;" },
  { zh: "郡縣相迫促，亦內相刻，流及衆庶。", literal: "commanderies and counties press each other in haste, also inwardly carve at one another, flowing down to the multitude.", idiomatic: "commanderies and counties press one another in haste, turn inward to cut at each other, and the harm reaches the common people." },
  { zh: "是故鄕黨闕於嘉賓之懽，九族忘其親親之恩，飲食周急之厚彌衰，送往勞來之禮不行。", literal: "Therefore in village communities the joy of honoring guests is lacking, the nine agnatic lines forget their kinship affection, the thick kindness of food and drink in relieving urgency grows ever thinner, and the rites of sending off the departed and welcoming the returning are not practiced.", idiomatic: "Hence village communities lack the joy of honoring guests, the nine agnatic lines forget kinship bonds, the generosity of sharing food in times of need grows ever thinner, and the rites of farewell and welcome fall away." },
  { zh: "夫人道不通則陰陽否隔，和氣不通，未必不由此也！", literal: "When the human Way is not open, then yin and yang are blocked apart and harmonious qi does not pass—perhaps it is not without this cause!", idiomatic: "When the human Way is blocked, yin and yang are cut off from one another and harmonious qi cannot flow—surely this is not unrelated!" },
  { zh: "《詩》云：『民之失德，乾餱以愆。", literal: "The Book of Songs says: \"When the people lose virtue, dried provisions become offense.", idiomatic: "The Book of Songs says: \"When the people lose virtue, even dried provisions become offense." },
  { zh: "』鄙語曰：『苛政不親，煩苦傷恩。", literal: "\" A vulgar saying says: \"Harsh government is not close; vexation and hardship wound affection.", idiomatic: "\" A common saying runs: \"Harsh government estranges kin; trouble and hardship wound affection." },
  { zh: "』方刺史奏事時，宜明申敕，使昭然知本朝之要務。", literal: "\" When Regional Inspectors report affairs, it is fitting clearly to admonish and instruct them, so that they plainly know this dynasty's essential affairs.", idiomatic: "\" When Regional Inspectors report affairs, Your Majesty should clearly instruct them so they plainly know this dynasty's essential duties." },
  { zh: "」上嘉納之。", literal: "\" The emperor praised and adopted it.", idiomatic: "\" The emperor praised and adopted it." },
  { zh: "----8　八月，有兩月相承，晨見東方。", literal: "----8 In the eighth month, two moons followed in succession, seen in the morning in the east.", idiomatic: "----8 In the eighth month, two moons appeared in succession, seen at dawn in the east." },
  { zh: "----9　冬，十二月，作長安南、北郊，罷甘泉、汾陰祠，及紫壇偽飾、女樂、鸞路、騂駒、龍馬、石壇之屬。", literal: "----9 In winter, the twelfth month, the southern and northern suburbs of Chang'an were built; sacrifices at Sweet Springs and Fenyin were abolished, along with purple-altar false adornments, female musicians, imperial phoenix carriages, red calves, dragon horses, stone altars, and the like.", idiomatic: "----9 In winter, the twelfth month, the southern and northern suburbs of Chang'an were established; sacrifices at Sweet Springs and Fenyin were abolished, along with purple-altar false adornments, female musicians, imperial phoenix carriages, red calves, dragon horses, stone altars, and the like." },
  { zh: "1　春，正月，罷雍五畤及陳寶祠，皆從匡衡之請也。", literal: "1. In spring, the first month, the Five Altars at Yong and the Chen Bao shrine were abolished—all following Kuang Heng's request.", idiomatic: "1. In spring, the first month, the Five Altars at Yong and the Chen Bao shrine were abolished—all at Kuang Heng's request." },
  { zh: "辛巳，上始郊祀長安南郊。", literal: "On xinsi, the emperor for the first time performed suburban sacrifice at Chang'an's southern suburb.", idiomatic: "On xinsi, the emperor for the first time sacrificed at Chang'an's southern suburb." },
  { zh: "赦奉郊縣及中都官耐罪徒；", literal: "a pardon was granted to counties attending the suburban sacrifice and to convict laborers of the central offices bearing punishment up to shaving the head;", idiomatic: "counties attending the suburban sacrifice and convict laborers of the central offices bearing punishment up to shaving the head were pardoned;" },
  { zh: "減天下賦錢，算四十。", literal: "the empire's tax money was reduced by forty per calculation.", idiomatic: "the empire's poll tax was reduced by forty per calculation." },
  { zh: "----2　閏月，以渭城延陵亭部爲初陵。", literal: "----2 In the intercalary month, the Yanling pavilion district of Weicheng was made the site of the first imperial tomb.", idiomatic: "----2 In the intercalary month, the Yanling pavilion district of Weicheng was made the site of the first imperial tomb." },
  { zh: "----3　三月，辛丑，上始祠-{后}-土于北郊。", literal: "----3 In the third month, on xinchou, the emperor for the first time sacrificed to -{后}- Earth at the northern suburb.", idiomatic: "----3 In the third month, on xinchou, the emperor for the first time sacrificed to -{后}- Earth at the northern suburb." },
  { zh: "----4　丙午，立皇后許氏。", literal: "----4 On bingwu, Empress Xu was established.", idiomatic: "----4 On bingwu, Empress Xu was established." },
  { zh: "后，車騎將軍嘉之女也。", literal: "The empress was the daughter of General of Chariots and Cavalry Xu Jia.", idiomatic: "The empress was the daughter of General of Chariots and Cavalry Xu Jia." },
  { zh: "元帝傷母恭哀后居位日淺而遭霍氏之辜，故選嘉女以配太子。", literal: "Emperor Yuan grieved that his mother Empress Gong'ai had held the throne briefly and suffered the guilt of the Huo clan, so he chose Jia's daughter to match the crown prince.", idiomatic: "Emperor Yuan, grieving that his mother Empress Gong'ai had reigned briefly and suffered the ruin of the Huo clan, chose Jia's daughter to wed the crown prince." },
  { zh: "----5　上自爲太子時，以好色聞；", literal: "----5 From the time he was crown prince, he was known for lust of color;", idiomatic: "----5 From his days as crown prince, he was known for lust;" },
  { zh: "及卽位，皇太后詔采良家女以備後宮。", literal: "when he succeeded the throne, the Empress Dowager ordered selection of good-family women to fill the rear palace.", idiomatic: "when he took the throne, the Empress Dowager ordered good-family women selected for the rear palace." },
  { zh: "大將軍武庫令杜欽說王鳳曰：「禮，一娶九女，所以廣嗣重祖也；", literal: "Grand General-in-Chief's Arsenal Commandant Du Qin urged Wang Feng, saying: \"By ritual, one marriage takes nine women, thereby to broaden heirs and honor ancestors;", idiomatic: "Grand General-in-Chief's Arsenal Commandant Du Qin urged Wang Feng, saying: \"By ritual, one marriage takes nine women, thereby to broaden heirs and honor ancestors;" },
  { zh: "娣姪雖缺不復補，所以養壽塞爭也。", literal: "younger consorts and nieces, though vacancies occur, are not replenished—thereby to nurture longevity and block strife.", idiomatic: "younger consorts and nieces, though vacancies occur, are not replenished—thereby to nurture longevity and block strife." },
  { zh: "故后妃有貞淑之行，則胤嗣有賢聖之君；", literal: "Therefore when empress and consorts have chaste and pure conduct, then heirs have sage and worthy rulers;", idiomatic: "Therefore when empress and consorts are chaste and pure, heirs produce sage and worthy rulers;" },
  { zh: "制度有威儀之節，則人君有壽考之福。", literal: "when institutions have the measure of majesty and ritual, then the human ruler has the blessing of long life.", idiomatic: "when institutions uphold majesty and ritual measure, the ruler enjoys the blessing of long life." },
  { zh: "廢而不由，則女德不厭；", literal: "If abandoned and not followed, then women's virtue is not satisfied;", idiomatic: "If abandoned and not followed, women's virtue is never satisfied;" },
  { zh: "女德不厭，則壽命不究於高年。", literal: "when women's virtue is not satisfied, then lifespan does not reach to advanced years.", idiomatic: "when women's virtue is not satisfied, lifespan does not reach advanced years." },
  { zh: "男子五十，好色未衰；", literal: "A man at fifty—lust of color is not yet declined;", idiomatic: "A man at fifty—lust is not yet spent;" },
  { zh: "婦人四十，容貌改前；", literal: "a woman at forty—her countenance has changed from before.", idiomatic: "a woman at forty—her looks have faded." },
  { zh: "以改前之容侍於未衰之年，而不以禮爲制，則其原不可救而後徠異態；", literal: "To serve with a countenance changed from before upon years not yet declined, yet not take ritual as regulation—then its origin cannot be saved and afterward strange attitudes come;", idiomatic: "To keep a faded face attending upon years not yet spent, without ritual as restraint—the root cannot be saved and strange passions follow;" },
  { zh: "後徠異態，則正后自疑而支庶有間適之心；", literal: "when strange attitudes come afterward, then the legitimate empress doubts herself and collateral lines have hearts of opportune fit;", idiomatic: "when strange passions follow, the legitimate empress grows doubtful and collateral lines harbor designs on succession;" },
  { zh: "是以晉獻被納讒之謗，申生蒙無罪之辜。", literal: "therefore Duke Xian of Jin suffered the slander of accepting calumny, and Shengheng bore guilt without crime.", idiomatic: "hence Duke Xian of Jin fell to calumny, and Prince Shengheng bore guilt though innocent." },
  { zh: "今聖主富於春秋，未有適嗣，方鄕術入學，未親后妃之議。", literal: "Now the sage ruler is rich in spring and autumn, has no legitimate heir, is just entering village-school learning, and has not yet personally attended to discussion of empress and consorts.", idiomatic: "Now the sage ruler is in the prime of youth, has no legitimate heir, is just entering his studies, and has not yet turned to the matter of empress and consorts." },
  { zh: "將軍輔政，宜因始初之隆，建九女之制，詳擇有行義之家，求淑女之質，毋必有聲色技能，爲萬世大法。", literal: "The general assists government; it is fitting, by virtue of the splendor at the beginning, to establish the institution of nine women, carefully choose households of conduct and righteousness, seek the substance of virtuous ladies, not necessarily requiring voice, color, or skill—to be the great law for ten thousand generations.", idiomatic: "The general assists government; you should seize this splendid beginning to establish the institution of nine women, carefully choose households of conduct and righteousness, seek virtuous ladies, and not demand voice, beauty, or skill—thereby setting the great law for ten thousand generations." },
  { zh: "夫少戒之在色，《小卞》之作，可爲寒心。", literal: "The caution of youth lies in lust of color—the composition \"Little Bian\" can make one chill the heart.", idiomatic: "Youth must guard against lust—the poem \"Little Bian\" is enough to chill the heart." },
  { zh: "唯將軍常以爲憂！", literal: "Only the general—take this as constant worry!", idiomatic: "Only let the general make this his constant worry!" },
  { zh: "」鳳白之太后，太后以爲故事無有；", literal: "\" Feng reported it to the Empress Dowager; the Empress Dowager considered that precedent had nothing of the kind;", idiomatic: "\" Feng reported it to the Empress Dowager; the Empress Dowager held that precedent offered no such model;" },
  { zh: "鳳不能自立法度，循故事而已。", literal: "Feng could not himself establish law and measure, and followed precedent only.", idiomatic: "Feng could not establish new institutions himself and followed precedent only." },
  { zh: "鳳素重欽，故置之莫府，國家政謀常與欽慮之，數稱達名士，裨正闕失；", literal: "Feng had long valued Qin, so he placed him in the privy office; state government and policy were often deliberated with Qin, and he repeatedly praised and advanced eminent scholars, supplementing and correcting omissions and errors;", idiomatic: "Feng had long valued Qin, so he placed him in the privy office; state policy was often deliberated with Qin, and he repeatedly praised and advanced eminent scholars, supplementing and correcting omissions;" },
  { zh: "當世善政多出於欽者。", literal: "the good policies of the age mostly came from Qin.", idiomatic: "many of the age's good policies came from Qin." },
  { zh: "----6　夏，大旱。", literal: "----6 In summer, great drought.", idiomatic: "----6 In summer, a great drought struck." },
  { zh: "----7　匈奴呼韓邪單于嬖左伊秩訾兄女二人；", literal: "----7 The Xiongnu Chanyu Huhanye favored the two daughters of the elder brother of Left Yizhi Zi;", idiomatic: "----7 The Xiongnu Chanyu Huhanye favored the two daughters of the elder brother of Left Yizhi Zi;" },
  { zh: "長女顓渠閼氏生二子，長曰且莫車，次曰囊知牙斯；", literal: "the elder daughter, Lady Zhuanqu, bore two sons—the elder called Chemoche, the younger Nangzhiyasi;", idiomatic: "the elder daughter, Lady Zhuanqu, bore two sons—the elder Chemoche, the younger Nangzhiyasi;" },
  { zh: "少女爲大閼氏，生四子，長曰雕陶莫皋，次曰且麋胥，皆長於且莫車，少子咸、樂二人，皆小於囊知牙斯。", literal: "the younger daughter was Great Lady, bore four sons—the elder called Diaotaomogao, the second Chemixi, both older than Chemoche; the younger sons Xian and Le, both younger than Nangzhiyasi.", idiomatic: "the younger daughter was Great Lady and bore four sons—the elder Diaotaomogao, the second Chemixi, both older than Chemoche; the younger sons Xian and Le, both younger than Nangzhiyasi." },
  { zh: "又他閼氏子十餘人。", literal: "Moreover, sons of other ladies numbered more than ten.", idiomatic: "Sons of other consorts numbered more than ten besides." },
  { zh: "顓渠閼氏貴，且莫車愛，呼韓邪病且死，欲立且莫車。", literal: "Lady Zhuanqu was honored and Chemoche beloved; Huhanye, ill and near death, wished to establish Chemoche.", idiomatic: "Lady Zhuanqu was honored and Chemoche beloved; Huhanye, ill and near death, wished to make Chemoche heir." },
  { zh: "顓渠閼氏曰：「匈奴亂十餘年，不絕如髮，賴蒙漢力，故得復安。", literal: "Lady Zhuanqu said: \"The Xiongnu were in disorder more than ten years, continuous as a thread; relying on Han strength, we were able to recover peace.", idiomatic: "Lady Zhuanqu said: \"The Xiongnu were in disorder more than ten years, hanging by a thread; relying on Han strength, we recovered peace." },
  { zh: "今平定未久，人民創艾戰鬭。", literal: "Now pacification is not yet long; the people are wounded by battle.", idiomatic: "Pacification is still new; the people are wounded by battle." },
  { zh: "且莫車年少，百姓未附，恐復危國。", literal: "Chemoche is young; the hundred clans are not yet attached—I fear the state will again be endangered.", idiomatic: "Chemoche is young and the people are not yet attached—I fear the state will again be endangered." },
  { zh: "我與大閼氏一家共子，不如立雕陶莫皋。", literal: "The Great Lady and I are one household sharing sons—it is better to establish Diaotaomogao.", idiomatic: "The Great Lady and I are one household sharing sons—it is better to establish Diaotaomogao." },
  { zh: "」大閼氏曰：「且莫車雖少，大臣共持國事。", literal: "\" Great Lady said: \"Though Chemoche is young, the great ministers jointly hold state affairs.", idiomatic: "\" Great Lady said: \"Though Chemoche is young, the great ministers jointly hold state affairs." },
  { zh: "今舍貴立賤，後世必亂。", literal: "Now to abandon the honored and establish the lowly—later generations will surely be in disorder.", idiomatic: "To abandon the honored and establish the lowly will surely bring disorder in later generations." },
  { zh: "」單于卒從顓渠閼氏計，立雕陶莫皋，約令傳國與弟。", literal: "\" The Chanyu finally followed Lady Zhuanqu's plan, established Diaotaomogao, and covenanted that the state should pass to a younger brother.", idiomatic: "\" The Chanyu finally followed Lady Zhuanqu's plan, established Diaotaomogao, and covenanted that the realm should pass to a younger brother." },
  { zh: "呼韓邪死，雕陶莫皋立，爲復株累若鞮單于。", literal: "Huhanye died; Diaotaomogao was established and became Chanyu Fuzhuleiruodi.", idiomatic: "Huhanye died; Diaotaomogao succeeded as Chanyu Fuzhuleiruodi." },
  { zh: "復株累若鞮單于以且麋胥爲左賢王，且莫車爲左谷蠡王，囊知牙斯爲右賢王。", literal: "Chanyu Fuzhuleiruodi made Chemixi Left Wise King, Chemoche Left Guli King, and Nangzhiyasi Right Wise King.", idiomatic: "Chanyu Fuzhuleiruodi made Chemixi Left Wise King, Chemoche Left Guli King, and Nangzhiyasi Right Wise King." },
  { zh: "復株累單于復妻王昭君，生二女，長女云爲須卜居次，小女爲當于居次。", literal: "Chanyu Fuzhuleiruodi again took Wang Zhaojun as wife; she bore two daughters—the elder called Yun was Lady Xubu Juci, the younger was Lady Dangyu Juci.", idiomatic: "Chanyu Fuzhuleiruodi again took Wang Zhaojun as wife; she bore two daughters—the elder Yun became Lady Xubu Juci, the younger Lady Dangyu Juci." },
  { zh: "1　春，三月，赦天下徒。", literal: "1. In spring, the third month, convict laborers throughout the empire were pardoned.", idiomatic: "1. In spring, the third month, convict laborers throughout the empire were pardoned." },
  { zh: "----2　秋，關內大雨四十餘日。", literal: "----2 In autumn, within the passes it rained more than forty days.", idiomatic: "----2 In autumn, within the passes it rained more than forty days." },
  { zh: "京師民相驚，言大水至；", literal: "The capital's people alarmed one another, saying great flood was coming;", idiomatic: "The people of the capital alarmed one another, saying a great flood was coming;" },
  { zh: "百姓奔走相蹂躪，老弱號呼，長安中大亂。", literal: "the hundred clans ran and trampled one another; old and weak cried out—great disorder in Chang'an.", idiomatic: "the people ran and trampled one another; old and weak cried out—Chang'an fell into great disorder." },
  { zh: "天子親御前殿，召公卿議。", literal: "The Son of Heaven personally attended the front hall and summoned dukes and ministers to deliberate.", idiomatic: "The emperor personally attended the front hall and summoned dukes and ministers to deliberate." },
  { zh: "大將軍鳳以為：「太后與上及後宮可御船，令吏民上長安城以避水。", literal: "Grand General-in-Chief Feng considered: \"The Empress Dowager, the emperor, and the rear palace can board boats; order clerks and commoners to ascend Chang'an's walls to avoid the water.", idiomatic: "Grand General-in-Chief Feng held: \"The Empress Dowager, the emperor, and the rear palace can board boats; order officials and people to ascend the walls of Chang'an to escape the flood." },
  { zh: "」君臣皆從鳳議。", literal: "\" Ruler and ministers all followed Feng's proposal.", idiomatic: "\" Ruler and ministers all followed Feng's proposal." },
  { zh: "左將軍王商獨曰：「自古無道之國，水猶不冒城郭；", literal: "Left General Wang Shang alone said: \"From antiquity in states without the Way, water still did not overflow walls and moats;", idiomatic: "Left General Wang Shang alone said: \"From antiquity, even in states without the Way, floods did not overrun walls and moats;" },
  { zh: "今政治和平，世無兵革，上下相安，何因當有大水一日暴至，此必訛言也！", literal: "now government is peaceful, the age has no arms and armor, above and below are at ease—what cause should there be for great flood to burst forth in one day? This must be false rumor!", idiomatic: "now government is peaceful, the age is free of war, above and below are at ease—why should a great flood burst upon us in a single day? This must be a false rumor!" },
  { zh: "不宜令上城，重驚百姓。", literal: "It is not fitting to order ascent to the walls and doubly alarm the hundred clans.", idiomatic: "It is not fitting to order people onto the walls and alarm the people twice over." },
  { zh: "」上乃止。", literal: "\" The emperor then stopped.", idiomatic: "\" The emperor then stopped." },
  { zh: "有頃，長安中稍定；", literal: "Before long, within Chang'an things gradually settled;", idiomatic: "Before long, Chang'an gradually settled;" },
  { zh: "問之，果訛言。", literal: "on inquiry, it was indeed false rumor.", idiomatic: "on inquiry, it proved a false rumor." },
  { zh: "上於是美壯商之固守，數稱其議；", literal: "The emperor thereupon praised Wang Shang the stalwart for his firm holding, and repeatedly extolled his proposal;", idiomatic: "The emperor thereupon praised stalwart Wang Shang for standing firm and repeatedly extolled his counsel;" },
  { zh: "而鳳大慚，自恨失言。", literal: "while Feng was greatly ashamed and hated himself for his mistaken words.", idiomatic: "while Feng was deeply ashamed and regretted his mistaken words." },
  { zh: "----3　上欲專委任王鳳，八月，策免車騎將軍許嘉，以特進侯就朝位。", literal: "----3 The emperor wished to entrust Wang Feng exclusively; in the eighth month, by edict he dismissed General of Chariots and Cavalry Xu Jia, who took his court seat as Marquis as Special Advancement.", idiomatic: "----3 The emperor wished to entrust Wang Feng exclusively; in the eighth month, by edict he dismissed General of Chariots and Cavalry Xu Jia, who took his court seat as Marquis as Special Advancement." },
  { zh: "----4　張譚坐選舉不實，免。", literal: "----4 Zhang Tan sat in guilt for untrue selection and was dismissed.", idiomatic: "----4 Zhang Tan was punished for untrue selection and was dismissed." },
  { zh: "冬，十月，光祿大夫尹忠為御史大夫。", literal: "In winter, the tenth month, Palace Counselor Yin Zhong became Censor-in-Chief.", idiomatic: "In winter, the tenth month, Palace Counselor Yin Zhong became Censor-in-Chief." },
  { zh: "----5　十二月，戊申朔，日有食之。", literal: "----5 In the twelfth month, on the first day of the month wushen, there was an eclipse of the sun.", idiomatic: "----5 In the twelfth month, on the first day of the month wushen, there was a solar eclipse." },
  { zh: "其夜，地震未央宮殿中。", literal: "That night, the earth quaked within the halls of Weiyang Palace.", idiomatic: "That night, the earth quaked within the halls of Weiyang Palace." },
  { zh: "詔舉賢良方正能直言極諫之士。", literal: "An edict summoned worthy and upright men able to speak bluntly and remonstrate to the utmost.", idiomatic: "An edict summoned worthy and upright men able to speak bluntly and remonstrate to the utmost." },
  { zh: "杜欽及太常丞谷永上對，皆以為後宮女寵太盛，嫉妒專上，將害繼嗣之咎。", literal: "Du Qin and Grand Master of Ceremonies Assistant Gu Yong submitted responses; all held that favor in the inner palace was too great, jealousy monopolized the ruler, and the fault would harm the succession.", idiomatic: "Du Qin and Grand Master of Ceremonies Assistant Gu Yong submitted responses; all held that favor in the inner palace was too great, jealousy monopolized the ruler, and the fault would harm the succession." },
  { zh: "----6　越巂山崩。", literal: "----6 In Yuexi, a mountain collapsed.", idiomatic: "----6 In Yuexi, a mountain collapsed." },
  { zh: "----7　丁丑，匡衡坐多取封邑四百頃，監臨盜所主守直十金以上，免為庶人。", literal: "----7 On dingchou, Kuang Heng sat in guilt for taking more than four hundred qing of his fief, overseeing theft, and the chief warden's straight value of more than ten jin of gold—he was dismissed as a commoner.", idiomatic: "----7 On dingchou, Kuang Heng was punished for taking more than four hundred qing of his fief, overseeing theft, and the chief warden's straight value of more than ten jin of gold—he was dismissed as a commoner." },
  { zh: "1　春，正月，癸卯，隕石於亳四，隕於肥累二。", literal: "1. In spring, the first month, on guimao, four meteorites fell at Bo and two at Feilei.", idiomatic: "1. In spring, the first month, on guimao, four meteorites fell at Bo and two at Feilei." },
  { zh: "-----2　罷中書宦官。", literal: "-----2 The eunuchs of the Secretariat were abolished.", idiomatic: "-----2 The eunuchs of the Secretariat were abolished." },
  { zh: "初置尚書員五人。", literal: "For the first time five posts of Master of Writing were established.", idiomatic: "For the first time five posts of Master of Writing were established." },
  { zh: "三月，甲申，以左將軍樂昌侯王商為丞相。", literal: "In the third month, on jiashen, Left General Marquis of Lechang Wang Shang was made Chancellor.", idiomatic: "In the third month, on jiashen, Left General Marquis of Lechang Wang Shang was made Chancellor." },
  { zh: "-----3　夏，上悉召前所舉直言之士，詣白虎殿對策。", literal: "-----3 In summer, the emperor summoned all those previously recommended for blunt speech and had them answer policy questions at the White Tiger Hall.", idiomatic: "-----3 In summer, the emperor summoned all those previously recommended for blunt speech and had them answer policy questions at the White Tiger Hall." },
  { zh: "是時上委政王鳳，議者多歸咎焉。", literal: "At this time the emperor entrusted government to Wang Feng, and many in the deliberations attributed blame to him.", idiomatic: "At this time the emperor entrusted government to Wang Feng, and many in the deliberations attributed blame to him." },
  { zh: "谷永知鳳方見柄用，陰欲自托，乃曰：「方今四夷賓服，皆為臣妾，北無熏葷、冒頓之患，南無趙佗、呂嘉之難，三垂晏然，靡有兵革之警。", literal: "Gu Yong knew Feng was then being wielded in power and secretly wished to attach himself; he therefore said: \"At present the four barbarians guest-submit—all are subjects and concubines; in the north there is no trouble of smoked meat and Modun, in the south no difficulty of Zhao Tuo and Lü Jia; the three frontiers are tranquil, without alarm of arms and armor.", idiomatic: "Gu Yong knew Feng was then being wielded in power and secretly wished to attach himself; he therefore said, \"At present the four barbarians guest-submit—all are subjects and concubines; in the north there is no trouble of the Xiongnu and Modun, in the south no difficulty of Zhao Tuo and Lü Jia; the three frontiers are tranquil, without alarm of arms and armor." },
  { zh: "諸侯大者乃食數縣，漢吏制其權柄，不得有為，無吳、楚、燕、梁之勢。", literal: "The greatest feudal lords eat only several counties; Han officials control their handles of power so they cannot act—there is no momentum of Wu, Chu, Yan, and Liang.", idiomatic: "The greatest feudal lords eat only several counties; Han officials control their handles of power so they cannot act—there is no momentum of Wu, Chu, Yan, and Liang." },
  { zh: "百官盤互，親疏相錯，骨肉大臣有申伯之忠，洞洞屬屬，小心畏忌，無重合、安陽、博陸之亂。", literal: "The hundred officials coil and interlock, near and far intermingled; flesh-and-bone great ministers have the loyalty of Duke of Shao, reverent and connected, careful and fearful—there is no disorder of Chonghe, Anyang, and Bolu.", idiomatic: "The hundred officials coil and interlock, near and far intermingled; flesh-and-bone great ministers have the loyalty of Duke of Shao, reverent and connected, careful and fearful—there is no disorder of Chonghe, Anyang, and Bolu." },
  { zh: "三者無毛髮之辜，竊恐陛下捨昭昭之白過，忽天地之明戒，聽晻昧之瞽說，歸咎乎無辜，倚異乎政事，重失天心，不可之大者也。", literal: "These three have not a hair's guilt; your servant fears Your Majesty will abandon the bright white fault, neglect Heaven and Earth's clear warnings, heed dim blind talk, attribute blame to the guiltless, lean on anomalies in government affairs, and again lose Heaven's heart—this is what must not be great.", idiomatic: "These three have not a hair's guilt; your servant fears Your Majesty will abandon the bright white fault, neglect Heaven and Earth's clear warnings, heed dim blind talk, attribute blame to the guiltless, lean on anomalies in government affairs, and again lose Heaven's heart—this is what must not be great." },
  { zh: "陛下誠深察愚臣之言，抗湛溺之意，解偏駁之愛，奮乾剛之威，平天覆之施，使列妾得人人更進，益納宜子婦人，毋擇好醜，毋避嘗字，毋論年齒。", literal: "If Your Majesty truly deeply examines your foolish servant's words, resists the intent of deep drowning, releases partial and one-sided favor, stirs the awesome yang firmness of Qian, levels Heaven's enveloping grace, enables the ranked concubines each in turn to advance, and further receives women fit to bear sons—do not choose beauty or ugliness, do not avoid trial characters, do not discuss age.", idiomatic: "If Your Majesty truly deeply examines your foolish servant's words, resists the intent of deep drowning, releases partial and one-sided favor, stirs the awesome yang firmness of Qian, levels Heaven's enveloping grace, enables the ranked concubines each in turn to advance, and further receives women fit to bear sons—do not choose beauty or ugliness, do not avoid trial characters, do not discuss age." },
  { zh: "推法言之，陛下得繼嗣於微賤之間，乃反為福；", literal: "Pushing the law to speak, if Your Majesty obtains a successor from among the slight and base, it is instead a blessing;", idiomatic: "Pushing the law to speak, if Your Majesty obtains a successor from among the slight and base, it is instead a blessing;" },
  { zh: "得繼嗣而已，母非有賤也。", literal: "once there is a successor, the mother is not thereby base.", idiomatic: "once there is a successor, the mother is not thereby base." },
  { zh: "後宮女史、使令有直意者，廣求於微賤之間，以遇天所開右，慰釋皇太后之憂慍，解謝上帝之譴怒，則繼嗣蕃滋，災異訖息！", literal: "Palace women clerks and attendants with upright intent—seek broadly among the slight and base to meet Heaven's opening and favor, soothe and release the Empress Dowager's worry and anger, answer and apologize to the Supreme God's censuring wrath—then the succession will flourish and multiply, and portents and anomalies will end!", idiomatic: "Palace women clerks and attendants with upright intent—seek broadly among the slight and base to meet Heaven's opening and favor, soothe and release the Empress Dowager's worry and anger, answer and apologize to the Supreme God's censuring wrath—then the succession will flourish and multiply, and portents and anomalies will end!" },
  { zh: "」杜欽亦仿此意。", literal: "\" Du Qin also followed this intent.", idiomatic: "\" Du Qin also followed this intent." },
  { zh: "上皆以其書示後宮，擢永為光祿大夫。", literal: "The emperor showed all their writings to the inner palace and promoted Yong to Palace Counselor.", idiomatic: "The emperor showed all their writings to the inner palace and promoted Yong to Palace Counselor." },
  { zh: "-----4　夏，四月，雨雪。", literal: "-----4 In summer, the fourth month, rain and snow fell.", idiomatic: "-----4 In summer, the fourth month, rain and snow fell." },
  { zh: "-----5　秋，桃、李實。", literal: "-----5 In autumn, peaches and plums bore fruit.", idiomatic: "-----5 In autumn, peaches and plums bore fruit." },
  { zh: "-----6　大雨水十餘日，河決東郡金堤。", literal: "-----6 Great rain fell for more than ten days; the Yellow River burst the Golden Dike in Dong Commandery.", idiomatic: "-----6 Great rain fell for more than ten days; the Yellow River burst the Golden Dike in Dong Commandery." },
  { zh: "先是清河都尉馮逡奏言：「郡承河下流，土壤輕脆易傷，頃所以闊無大害者，以屯氏河通兩川分流也。", literal: "Earlier Commandery Commandant of Qinghe Feng Xun memorialized, saying: \"The commandery bears the river's lower course; the soil is light, brittle, and easily harmed. The reason in recent times there has been breadth without great harm is that the Tunshi River connected two streams for divided flow.", idiomatic: "Earlier Commandery Commandant of Qinghe Feng Xun memorialized, saying, \"The commandery bears the river's lower course; the soil is light, brittle, and easily harmed. The reason in recent times there has been breadth without great harm is that the Tunshi River connected two streams for divided flow." },
  { zh: "今屯氏河塞，靈鳴犢口又益不利，獨一川兼受數河之任，雖高增堤防，終不能洩。", literal: "Now the Tunshi River is blocked, and the Lingming Dukou is further unfavorable; a single stream alone bears the burden of several rivers—even if dikes are raised high, in the end it cannot drain.", idiomatic: "Now the Tunshi River is blocked, and the Lingming Dukou is further unfavorable; a single stream alone bears the burden of several rivers—even if dikes are raised high, in the end it cannot drain." },
  { zh: "如有霖雨，旬日不霽，必盈溢。", literal: "If there is prolonged rain and for ten days it does not clear, it will certainly brim and overflow.", idiomatic: "If there is prolonged rain and for ten days it does not clear, it will certainly brim and overflow." },
  { zh: "九河故跡，今既滅難明，屯氏河新絕未久，其處易浚；", literal: "The old traces of the Nine Rivers are now extinguished and hard to clarify; the Tunshi River was newly cut off not long ago—its place is easy to dredge;", idiomatic: "The old traces of the Nine Rivers are now extinguished and hard to clarify; the Tunshi River was newly cut off not long ago—its place is easy to dredge;" },
  { zh: "又其口所居高，於以分殺水力，道裡便宜，可復浚以助大河，洩暴水，備非常。", literal: "moreover its mouth stands high, whereby to divide and reduce the water's force—the route and distance are convenient; it may be dredged again to assist the great river, drain violent water, and guard against the extraordinary.", idiomatic: "moreover its mouth stands high, whereby to divide and reduce the water's force—the route and distance are convenient; it may be dredged again to assist the great river, drain violent water, and guard against the extraordinary." },
  { zh: "不豫修治，北決病四、五郡，南決病十餘郡，然後憂之，晚矣！", literal: "If one does not beforehand repair and govern, a north breach will afflict four or five commanderies and a south breach more than ten commanderies—only then to worry is late!", idiomatic: "If one does not beforehand repair and govern, a north breach will afflict four or five commanderies and a south breach more than ten commanderies—only then to worry is late!" },
  { zh: "」事下丞相、御史，白遣博士許商行視，以為「方用度不足，可且勿浚。", literal: "\" The matter was sent down to the Chancellor and Censor; they reported sending Erudite Xu Shang to inspect on site, holding that \"funds are presently insufficient; dredging may for now be deferred.", idiomatic: "\" The matter was sent down to the Chancellor and Censor; they reported sending Erudite Xu Shang to inspect on site, holding that \"funds are presently insufficient; dredging may for now be deferred." },
  { zh: "」後三歲，河果決於館陶及東郡金堤，氾濫兗、豫，入平原、千乘、濟南，凡灌四郡、三十二縣，水居地十五萬餘頃，深者三丈；", literal: "\" Three years later the river indeed burst at Guantao and the Golden Dike of Dong Commandery, flooding Yan and Yu, entering Pingyuan, Qiancheng, and Jinan—in all inundating four commanderies and thirty-two counties; water covered more than 150,000 qing of land, in deep places three zhang;", idiomatic: "\" Three years later the river indeed burst at Guantao and the Golden Dike of Dong Commandery, flooding Yan and Yu, entering Pingyuan, Qiancheng, and Jinan—in all inundating four commanderies and thirty-two counties; water covered more than 150,000 qing of land, in deep places three zhang;" },
  { zh: "壞敗官亭、室廬且四萬所。", literal: "government lodges and dwellings destroyed numbered nearly forty thousand.", idiomatic: "government lodges and dwellings destroyed numbered nearly forty thousand." },
  { zh: "-----7　冬，十一月，御史大夫尹忠以對方略疏闊，上切責其不憂職，自殺。", literal: "-----7 In winter, the eleventh month, Censor-in-Chief Yin Zhong, because his policy response was broad and loose, was sharply blamed by the emperor for not caring for his office and killed himself.", idiomatic: "-----7 In winter, the eleventh month, Censor-in-Chief Yin Zhong, because his policy response was broad and loose, was sharply blamed by the emperor for not caring for his office and killed himself." },
  { zh: "遣大司農非調調均錢谷河決所灌之郡，謁者二人發河南以東船五百□叟，徙民避水居丘陵九萬七千餘口。", literal: "The Grand Minister of Agriculture Fei Diao was sent to equalize money and grain in the commanderies flooded by the river breach; two Masters of Ceremonies dispatched from east of Henan five hundred □ boats, relocating the people to avoid the water to dwell on hills and mounds—more than ninety-seven thousand mouths.", idiomatic: "The Grand Minister of Agriculture Fei Diao was sent to equalize money and grain in the commanderies flooded by the river breach; two Masters of Ceremonies dispatched from east of Henan five hundred □ boats, relocating the people to avoid the water to dwell on hills and mounds—more than ninety-seven thousand mouths." },
  { zh: "-----8　壬戌，以少府張忠為御史大夫。", literal: "-----8 On renxu, Privy Treasurer Zhang Zhong was made Censor-in-Chief.", idiomatic: "-----8 On renxu, Privy Treasurer Zhang Zhong was made Censor-in-Chief." },
  { zh: "-----9　南山群盜傰宗等數百人為吏民害。", literal: "-----9 In the southern mountains, the bandit chieftain Zong and others, several hundred men, harmed officials and people.", idiomatic: "-----9 In the southern mountains, the bandit chieftain Zong and others, several hundred men, harmed officials and people." },
  { zh: "詔發兵千人逐捕，歲餘不能禽。", literal: "An edict dispatched a thousand troops to pursue and capture them; after more than a year they could not be taken.", idiomatic: "An edict dispatched a thousand troops to pursue and capture them; after more than a year they could not be taken." },
  { zh: "或說大將軍鳳，以「賊數百人在轂下，討不能得，難以示四夷；", literal: "Someone advised Chief Minister Feng, saying: \"Several hundred bandits are beneath the capital hub; if they cannot be taken when attacked, it is hard to show this to the four barbarians;", idiomatic: "Someone advised Chief Minister Feng, saying, \"Several hundred bandits are beneath the capital hub; if they cannot be taken when attacked, it is hard to show this to the four barbarians;" },
  { zh: "獨選賢京兆尹乃可。", literal: "only by selecting a worthy Metropolitan Governor will it do.", idiomatic: "only by selecting a worthy Metropolitan Governor will it do." },
  { zh: "」於是鳳薦故高陵令王尊，征為諫大夫，守京輔都尉，行京兆尹事。", literal: "\" Thereupon Feng recommended former Magistrate of Gaoling Wang Zun, summoned him as Remonstrance Grandee, made him Guard Commandant of the Capital Region, and had him act as Metropolitan Governor.", idiomatic: "\" Thereupon Feng recommended former Magistrate of Gaoling Wang Zun, summoned him as Remonstrance Grandee, made him Guard Commandant of the Capital Region, and had him act as Metropolitan Governor." },
  { zh: "旬月間，盜賊清；", literal: "Within a ten-day month, bandits were cleared;", idiomatic: "Within a month, bandits were cleared;" },
  { zh: "後拜為京兆尹。", literal: "afterward he was appointed Metropolitan Governor.", idiomatic: "afterward he was appointed Metropolitan Governor." },
  { zh: "-----10　上即位之初，丞相匡衡復奏：「射聲校尉陳湯以吏二千石奉使，顓命蠻夷中，不正身以先下，而盜所收康居財物，戒官屬曰：『絕域事不覆校。", literal: "-----10 At the beginning of the emperor's accession, Chancellor Kuang Heng again memorialized: \"Commandant of the Archers Chen Tang, as an official of two thousand dan on mission, gave arbitrary orders among the barbarians, did not correct his person to lead those below, yet stole goods received from Kangju, and warned his subordinates, saying: 'Matters beyond the frontier are not re-examined.", idiomatic: "-----10 At the beginning of the emperor's accession, Chancellor Kuang Heng again memorialized, \"Commandant of the Archers Chen Tang, as an official of two thousand dan on mission, gave arbitrary orders among the barbarians, did not correct his person to lead those below, yet stole goods received from Kangju, and warned his subordinates, saying, 'Matters beyond the frontier are not re-examined." },
  { zh: "』雖在赦前，不宜處位。", literal: "' Though it was before an amnesty, he ought not hold office.", idiomatic: "' Though it was before an amnesty, he ought not hold office." },
  { zh: "」湯坐免。", literal: "\" Tang sat in guilt and was dismissed.", idiomatic: "\" Tang was punished and dismissed." },
  { zh: "後湯上言：「康居王侍子，非王子。", literal: "Later Tang submitted a statement: \"The attendant son of the King of Kangju is not a prince.", idiomatic: "Later Tang submitted a statement, \"The attendant son of the King of Kangju is not a prince." },
  { zh: "」按驗，實王子也。", literal: "\" On investigation it proved he was indeed a prince.", idiomatic: "\" On investigation it proved he was indeed a prince." },
  { zh: "湯下獄當死。", literal: "Tang was imprisoned and ought to die.", idiomatic: "Tang was imprisoned and ought to die." },
  { zh: "太中大夫谷永上疏訟湯曰：「臣聞楚有子玉得臣，文公為之仄席而坐；", literal: "Grand Palace Counselor Gu Yong submitted a memorial pleading for Tang, saying: \"Your servant has heard that when Chu had Ziyu obtain his minister, Duke Wen for him sat on a tilted mat;", idiomatic: "Grand Palace Counselor Gu Yong submitted a memorial pleading for Tang, saying, \"Your servant has heard that when Chu had Ziyu obtain his minister, Duke Wen for him sat on a tilted mat;" },
  { zh: "趙有廉頗、馬服，強秦不敢窺兵井陘；", literal: "when Zhao had Lian Po and Lord of Mafu, mighty Qin did not dare peep at troops at Jingxing;", idiomatic: "when Zhao had Lian Po and Lord of Mafu, mighty Qin did not dare peep at troops at Jingxing;" },
  { zh: "近漢有郅都、魏尚，匈奴不敢南鄉沙幕。", literal: "in recent Han there were Zhi Du and Wei Shang, and the Xiongnu did not dare turn south toward the sandy curtain.", idiomatic: "in recent Han there were Zhi Du and Wei Shang, and the Xiongnu did not dare turn south toward the sandy curtain." },
  { zh: "由是言之，戰克之將，國之爪牙，不可不重也。", literal: "From this to speak, generals who conquer in battle are the state's claws and teeth—they cannot but be heavily valued.", idiomatic: "From this to speak, generals who conquer in battle are the state's claws and teeth—they cannot but be heavily valued." },
  { zh: "蓋君子聞鼓鼙之聲，則思將帥之臣。", literal: "The noble man, hearing the sound of drums and war-drums, then thinks of generals and commanders.", idiomatic: "The noble man, hearing the sound of drums and war-drums, then thinks of generals and commanders." },
  { zh: "竊見關內侯陳湯，前斬郅支，威震百蠻，武暢西海，漢元以來，征伐方外之將，未嘗有也。", literal: "Your servant has observed Marquis Within the Passes Chen Tang, who before beheaded Zhizhi, awed the hundred barbarians, and whose martial prowess reached the western sea—since Emperor Yuan of Han, among generals who campaigned beyond the borders, there has never been his like.", idiomatic: "Your servant has observed Marquis Within the Passes Chen Tang, who before beheaded Zhizhi, awed the hundred barbarians, and whose martial prowess reached the western sea—since Emperor Yuan, among generals who campaigned beyond the borders, there has never been his like." },
  { zh: "今湯坐言事非是，幽囚久系，歷時不決，執憲之吏欲致之大辟。", literal: "Now Tang sits in guilt because his words on the matter were not correct, is darkly imprisoned and long bound, passes seasons without decision, and the officers who uphold the law wish to bring him to the great execution.", idiomatic: "Now Tang is punished because his words on the matter were not correct, is darkly imprisoned and long bound, passes seasons without decision, and the officers who uphold the law wish to bring him to the great execution." },
  { zh: "昔白起為秦將，南拔郢都，北坑趙括，以纖介之過，賜死杜郵；", literal: "Formerly Bai Qi was Qin's general, south took Yingdu, north buried Zhao Kuo alive—for a minute fault he was granted death at Duyou;", idiomatic: "Formerly Bai Qi was Qin's general, south took Yingdu, north buried Zhao Kuo alive—for a minute fault he was granted death at Duyou;" },
  { zh: "秦民憐之，莫不隕涕。", literal: "the people of Qin pitied him; none did not fall in tears.", idiomatic: "the people of Qin pitied him; none did not fall in tears." },
  { zh: "今湯親秉鉞席捲，喋血萬里之外，薦功祖廟，告類上帝，介冑之士靡不慕義。", literal: "Now Tang personally grasped the battle-axe and rolled up the mat, blood-smeared ten thousand li beyond, presented achievement at the ancestral temple, and reported to the Supreme God—men in armor and helmet none did not admire his righteousness.", idiomatic: "Now Tang personally grasped the battle-axe and rolled up the mat, blood-smeared ten thousand li beyond, presented achievement at the ancestral temple, and reported to the Supreme God—men in armor and helmet none did not admire his righteousness." },
  { zh: "以言事為罪，無赫赫之惡。", literal: "To make words on a matter a crime—there is no glaring evil.", idiomatic: "To make words on a matter a crime—there is no glaring evil." },
  { zh: "《周書》曰：『記人之功，忘人之過，宜為君者也。", literal: "The Book of Zhou says: 'Record men's achievements, forget men's faults—this is fitting for a ruler.", idiomatic: "The Book of Zhou says, 'Record men's achievements, forget men's faults—this is fitting for a ruler." },
  { zh: "』夫犬馬有勞於人，尚加帷蓋之報，況國之功臣者哉！", literal: "' For dogs and horses that have toiled for men, there is still added the reward of canopy and cover—how much more the state's meritorious ministers!", idiomatic: "' For dogs and horses that have toiled for men, there is still added the reward of canopy and cover—how much more the state's meritorious ministers!" },
  { zh: "竊恐陛下忽於鼙鼓之聲，不察《周書》之意，而忘帷蓋之施，庸臣遇湯，卒從吏議，使百姓介然有秦民之恨，非所以厲死難之臣也！", literal: "Your servant fears Your Majesty will neglect the sound of war-drums, not examine the intent of the Book of Zhou, and forget the bestowal of canopy and cover; a mediocre minister meets Tang and in the end follows the clerks' deliberation, making the hundred surnames sharply harbor the resentment of Qin's people—this is not the means to encourage ministers who die in hardship!", idiomatic: "Your servant fears Your Majesty will neglect the sound of war-drums, not examine the intent of the Book of Zhou, and forget the bestowal of canopy and cover; a mediocre minister meets Tang and in the end follows the clerks' deliberation, making the hundred surnames sharply harbor the resentment of Qin's people—this is not the means to encourage ministers who die in hardship!" },
  { zh: "書奏，天子出湯，奪爵為士伍。", literal: "When the memorial was submitted, the Son of Heaven released Tang and stripped his rank to common soldier.", idiomatic: "When the memorial was submitted, the emperor released Tang and stripped his rank to common soldier." },
  { zh: "會西域都護段會宗為烏孫兵所圍，驛騎上書，願發城郭、敦煌兵以自救；", literal: "It happened that Protector-General of the Western Regions Duan Huizong was besieged by Wusun troops; post relay riders submitted a memorial wishing to dispatch troops from the walled cities and Dunhuang to save themselves;", idiomatic: "It happened that Protector-General of the Western Regions Duan Huizong was besieged by Wusun troops; post relay riders submitted a memorial wishing to dispatch troops from the walled cities and Dunhuang to save themselves;" },
  { zh: "丞相商、大將軍鳳及百寮議數日不決。", literal: "Chancellor Shang, Chief Minister Feng, and the hundred officials deliberated for several days without decision.", idiomatic: "Chancellor Shang, Chief Minister Feng, and the hundred officials deliberated for several days without decision." },
  { zh: "鳳言：「陳湯多籌策，習外國事，可問。", literal: "Feng said: \"Chen Tang has many stratagems and is practiced in foreign affairs—he may be asked.", idiomatic: "Feng said, \"Chen Tang has many stratagems and is practiced in foreign affairs—he may be asked." },
  { zh: "」上召湯見宣室。", literal: "\" The emperor summoned Tang to an audience in the Hall of Illumination.", idiomatic: "\" The emperor summoned Tang to an audience in the Hall of Illumination." },
  { zh: "湯擊郅支時中寒，病兩臂不屈申；", literal: "When Tang struck Zhizhi he caught cold within; his two arms were diseased and would not bend or extend;", idiomatic: "When Tang struck Zhizhi he caught cold within; his two arms were diseased and would not bend or extend;" },
  { zh: "湯入見，有詔毋拜，示以會宗奏。", literal: "Tang entered audience; there was an edict not to bow, and Huizong's memorial was shown him.", idiomatic: "Tang entered audience; there was an edict not to bow, and Huizong's memorial was shown him." },
  { zh: "湯對曰：「臣以為此必無可憂也。", literal: "Tang replied: \"Your servant considers this certainly has nothing to worry about.", idiomatic: "Tang replied, \"Your servant considers this certainly has nothing to worry about." },
  { zh: "」上曰：「何以言之？", literal: "\" The emperor said: \"By what do you speak thus?\"", idiomatic: "\" The emperor said, \"By what do you speak thus?\"" },
  { zh: "」湯曰：「夫胡兵五而當漢兵一，何者？", literal: "\" Tang said: \"Barbarian troops are five to match one Han troop—why?", idiomatic: "\" Tang said, \"Barbarian troops are five to match one Han troop—why?" },
  { zh: "兵刃樸鈍，弓弩不利。", literal: "Weapons and blades are crude and blunt; bows and crossbows are not sharp.", idiomatic: "Weapons and blades are crude and blunt; bows and crossbows are not sharp." },
  { zh: "今聞頗得漢巧，然猶三而當一。", literal: "Now I hear they have somewhat obtained Han skill, yet still it is three to one.", idiomatic: "Now I hear they have somewhat obtained Han skill, yet still it is three to one." },
  { zh: "又《兵法》曰：『客倍而主人半，然後敵。", literal: "Moreover the Art of War says: 'When the guest is doubled and the host is halved, then they can be enemies.", idiomatic: "Moreover the Art of War says, 'When the guest is doubled and the host is halved, then they can be enemies." },
  { zh: "』今圍會宗者人眾不足以勝會宗。", literal: "' Now those besieging Huizong in numbers are insufficient to overcome Huizong.", idiomatic: "' Now those besieging Huizong in numbers are insufficient to overcome Huizong." },
  { zh: "唯陛下勿憂！", literal: "Only may Your Majesty not worry!", idiomatic: "Only may Your Majesty not worry!" },
  { zh: "且兵輕行五十里，重行三十里，今會宗欲發城郭、敦煌，歷時乃至，所謂報讎之兵，非救急之用也。", literal: "Moreover troops lightly marching go fifty li, heavily marching thirty li; now if Huizong wishes to dispatch from the walled cities and Dunhuang, it will take seasons to arrive—this is what is called troops for revenge, not for saving the urgent.", idiomatic: "Moreover troops lightly marching go fifty li, heavily marching thirty li; now if Huizong wishes to dispatch from the walled cities and Dunhuang, it will take seasons to arrive—this is what is called troops for revenge, not for saving the urgent." },
  { zh: "」上曰：「奈何？", literal: "\" The emperor said: \"What then?", idiomatic: "\" The emperor said, \"What then?" },
  { zh: "其解可必乎？", literal: "Can the lifting of the siege be certain?", idiomatic: "Can the lifting of the siege be certain?" },
  { zh: "度何時解？", literal: "Estimate when it will be lifted?\"", idiomatic: "Estimate when it will be lifted?\"" },
  { zh: "」湯知烏孫瓦合，不能久攻，故事不過數日，因對曰：「已解矣！", literal: "\" Tang knew the Wusun were tiles joined and could not attack long; such matters do not pass several days; he therefore replied: \"It is already lifted!", idiomatic: "\" Tang knew the Wusun were tiles joined and could not attack long; such matters do not pass several days; he therefore replied, \"It is already lifted!" },
  { zh: "」屈指計其日，曰：「不出五日，當有吉語聞。", literal: "\" He bent his fingers and counted the days, saying: \"Within no more than five days there should be good news heard.", idiomatic: "\" He bent his fingers and counted the days, saying, \"Within no more than five days there should be good news heard." },
  { zh: "」居四日，軍書到，言已解。", literal: "\" After four days, military documents arrived reporting it was already lifted.", idiomatic: "\" After four days, military documents arrived reporting it was already lifted." },
  { zh: "大將軍鳳奏以為從事中郎，莫府事壹決於湯。", literal: "Chief Minister Feng memorialized to make him Attendant Gentleman; all staff affairs were decided solely by Tang.", idiomatic: "Chief Minister Feng memorialized to make him Attendant Gentleman; all staff affairs were decided solely by Tang." },
  { zh: "1 　 春，杜欽薦犍為王延世於王鳳，使塞決河。", literal: "1. In spring, Du Qin recommended Wang Yanshi of Jianwei to Wang Feng to block the burst river.", idiomatic: "1. In spring, Du Qin recommended Wang Yanshi of Jianwei to Wang Feng to block the burst river." },
  { zh: "鳳以延世為河堤使者。", literal: "Feng made Yanshi River-Dike Commissioner.", idiomatic: "Feng made Yanshi River-Dike Commissioner." },
  { zh: "延世以竹落長四丈，大九圍，盛以小石，兩船夾載而下之。", literal: "Yanshi used bamboo gabions four zhang long and nine wei in girth, filled with small stones, and had two boats clamp and carry them down.", idiomatic: "Yanshi used bamboo gabions four zhang long and nine wei in girth, filled with small stones, and had two boats clamp and carry them down." },
  { zh: "三十六日，河堤成。", literal: "In thirty-six days the river dike was completed.", idiomatic: "In thirty-six days the river dike was completed." },
  { zh: "三月，詔以延世為光祿大夫，秩中二千石，賜爵關內侯、黃金百斤。", literal: "In the third month, an edict made Yanshi Palace Counselor, rank at middle two thousand dan, and granted the title Marquis Within the Passes and a hundred jin of gold.", idiomatic: "In the third month, an edict made Yanshi Palace Counselor, rank at middle two thousand dan, and granted the title Marquis Within the Passes and a hundred jin of gold." },
  { zh: "2　  夏，四月，己亥晦，日有食之。", literal: "2. In summer, the fourth month, on the last day of the month jihai, there was an eclipse of the sun.", idiomatic: "2. In summer, the fourth month, on the last day of the month jihai, there was a solar eclipse." },
  { zh: "詔公卿百僚陳過失，無有所諱。", literal: "An edict ordered the Three Dukes, ministers, and hundred officials to state faults without anything concealed.", idiomatic: "An edict ordered the Three Dukes, ministers, and hundred officials to state faults without anything concealed." },
  { zh: "大赦天下。", literal: "A great amnesty was proclaimed for the empire.", idiomatic: "A great amnesty was proclaimed for the empire." },
  { zh: "光祿大夫劉向對曰：「四月交於五月，月同孝惠，日同孝昭，其占恐害繼嗣。", literal: "Palace Counselor Liu Xiang replied: \"The fourth month crosses into the fifth; the moon is the same as Emperor Xiaohui's, the sun the same as Emperor Xiaozhao's—the omen fears harm to the succession.", idiomatic: "Palace Counselor Liu Xiang replied, \"The fourth month crosses into the fifth; the moon is the same as Emperor Xiaohui's, the sun the same as Emperor Xiaozhao's—the omen fears harm to the succession." },
  { zh: "」是時許皇后專寵，後宮希得進見，中外皆憂上無繼嗣，故杜欽、谷永及向所對皆及之。", literal: "\" At this time Empress Xu monopolized favor; in the inner palace few obtained audience; within and without all worried the emperor had no successor—therefore the responses of Du Qin, Gu Yong, and Xiang all touched on this.", idiomatic: "\" At this time Empress Xu monopolized favor; in the inner palace few obtained audience; within and without all worried the emperor had no successor—therefore the responses of Du Qin, Gu Yong, and Xiang all touched on this." },
  { zh: "上於是減省椒房、掖廷用度，服御、輿駕所發諸官署及所造作，遺賜外家、群臣妾，皆如竟寧以前故事。", literal: "The emperor thereupon reduced and cut the expenditures of the Pepper Chambers and the Rear Palace; what was issued from the wardrobe, carriages, and equipage to the various offices and what was made, and gifts to the maternal kin and the various ministers' concubines, all followed the precedents before Jingning.", idiomatic: "The emperor thereupon reduced expenditures in the Pepper Chambers and the Rear Palace; issues from the wardrobe, carriages, and equipage to the various offices, items ordered made, and gifts to the maternal kin and ministers' concubines all followed the precedents before Jingning." },
  { zh: "皇后上疏自陳，以為：「時世異制，長短相補，不出漢制而已，纖微之間未必可同。", literal: "The empress submitted a memorial stating herself, holding: \"Times and generations differ in institutions; long and short complement each other—they do not go outside Han institutions alone, and in fine details they need not be the same.", idiomatic: "The empress submitted a memorial in her own defense, arguing, \"Times differ in institutions; long and short complement each other—they need only stay within Han institutions, and fine details need not match exactly." },
  { zh: "若竟寧前與黃龍前，豈相放哉！", literal: "If before Jingning and before Huanglong, how could they be made to match!", idiomatic: "If the period before Jingning and the period before Huanglong—how could they be made to match!" },
  { zh: "家吏不曉，今壹受詔如此，且使妾搖手不得。", literal: "Household clerks do not understand; now all at once receive an edict like this, and it makes your concubine unable even to wave her hand.", idiomatic: "Household clerks do not understand; now they all receive an edict like this at once, and it leaves your concubine unable even to lift a hand." },
  { zh: "設妾欲作某屏風張於某所，曰：『故事無有。", literal: "Suppose your concubine wishes to make a certain screen and hang it at a certain place—they say, 'There is no precedent.", idiomatic: "Suppose your concubine wishes to make a certain screen and hang it in a certain place—they say, 'There is no precedent." },
  { zh: "』或不能得，則必繩妾以詔書矣。", literal: "' Or if she cannot obtain it, they are sure to bind your concubine with the edict.", idiomatic: "' Or if she cannot obtain it, they are sure to bind your concubine with the edict." },
  { zh: "此誠不可行，唯陛下省察！", literal: "This truly cannot be carried out—only Your Majesty examine it!", idiomatic: "This truly cannot be carried out—only Your Majesty will examine it!" },
  { zh: "故事，以特牛祠大父母，戴侯、敬侯皆得蒙恩以太牢祠，今當率如故事，唯陛下哀之！", literal: "By precedent, a special ox is used to sacrifice to great-grandparents; Marquis Dai and Marquis Jing both received grace to sacrifice with the great offering—now it ought to follow precedent as before; only Your Majesty pity it!", idiomatic: "By precedent a special ox is used to sacrifice to great-grandparents; Marquis Dai and Marquis Jing both received grace to sacrifice with the great offering—now it ought to follow precedent as before; only Your Majesty will pity me!" },
  { zh: "今吏甫受詔讀記，直豫言使後知之，非可復若私府有所取也。", literal: "Now when clerks have just received the edict and read the record, they straightway foretell and let those behind know—it is not possible again as when the private residence took what it wished.", idiomatic: "Now when clerks have just received the edict and read the record, they straightway announce it in advance so those behind will know—it cannot again be as when the private residence took what it wished." },
  { zh: "其萌牙所以約制妾者，恐失人理。", literal: "These first sprouts by which to bind and restrain your concubine—I fear they lose human reason.", idiomatic: "These first measures to bind and restrain your concubine—I fear they violate human decency." },
  { zh: "唯陛下深察焉！", literal: "Only Your Majesty deeply examine it!", idiomatic: "Only Your Majesty will examine it deeply!" },
  { zh: "」上於是采谷永、劉向所言災異咎驗皆在後宮之意以報之，且曰：「吏拘於法，亦安足過！", literal: "\" The emperor thereupon adopted the meaning of what Gu Yong and Liu Xiang had said—that portents, anomalies, blame, and verification all lay in the rear palace—to reply to her, and moreover said: \"Clerks are bound by law—how is that enough to fault!", idiomatic: "\" The emperor thereupon adopted the meaning of what Gu Yong and Liu Xiang had said—that portents, anomalies, blame, and verification all lay in the rear palace—to reply to her, and moreover said, \"Clerks are bound by law—how is that enough to fault!" },
  { zh: "蓋矯枉者過直，古今同之。", literal: "For one who straightens what is bent goes past straight—ancient and modern are the same in this.", idiomatic: "For one who straightens what is bent overshoots the mark—ancient and modern are the same in this." },
  { zh: "且財幣之省，特牛之祠，其於皇后，所以扶助德美，為華寵也。", literal: "Moreover, the cutting of wealth and currency and the sacrifice with the special ox—for the empress they are means to support virtue and beauty and make splendor and favor.", idiomatic: "Moreover, cutting expenditures and the sacrifice with the special ox—for the empress they are means to support virtue and beauty and confer splendor and favor." },
  { zh: "咎根不除，災變相襲，祖宗且不血食，何戴侯也！", literal: "If the root of blame is not removed, disasters and changes succeed one another—even the ancestors will not have blood offerings; what of Marquis Dai!", idiomatic: "If the root of blame is not removed, disasters and changes succeed one another—even the ancestors will lack blood offerings; what of Marquis Dai!" },
  { zh: "傳不云乎：『以約失之者鮮』，審皇后欲從其奢與？", literal: "Does the Classic not say: 'He who errs through restraint is rare'—does the empress truly wish to follow extravagance?", idiomatic: "Does the Classic not say, 'He who errs through restraint is rare'—does the empress truly wish to follow extravagance?" },
  { zh: "朕亦當法孝武皇帝也。", literal: "We too ought to take Emperor Xiao Wu as model.", idiomatic: "We too ought to take Emperor Wu as our model." },
  { zh: "如此，則甘泉、建章可復興矣。", literal: "If so, Ganquan and Jianzhang can be revived again.", idiomatic: "If so, Ganquan and Jianzhang can be revived again." },
  { zh: "孝文皇帝，朕之師也。", literal: "Emperor Xiao Wen is Our teacher.", idiomatic: "Emperor Wen is Our teacher." },
  { zh: "皇太后，皇后成法也。", literal: "The empress dowager and the empress are the completed standard.", idiomatic: "The empress dowager and the empress are the established standard." },
  { zh: "假使太后在彼時不如職，今見親厚，又惡可以逾乎！", literal: "Suppose the empress dowager at that time did not match her office—now she is seen as close and generous; how again can one exceed it!", idiomatic: "Suppose the empress dowager at that time did not match her office—now she is seen as close and generous; how again can one exceed it!" },
  { zh: "皇后其刻心秉德，謙約為右，垂則列妾，使有法焉！", literal: "The empress should carve her heart and hold to virtue, take modest restraint as foremost, hang her standard for the ranks of concubines, and make them have law!", idiomatic: "The empress should carve her heart and hold to virtue, take modest restraint as foremost, set her standard for the ranks of concubines, and give them a proper model!" },
  { zh: "3　給事中平陵平當上言：「太上皇，漢之始祖，廢其寢廟園，非是。", literal: "3 Palace Attendant Ping Dang of Pingling submitted a statement: \"The Grand Supreme Emperor is Han's founding ancestor—to abolish his temple park and garden is not right.", idiomatic: "3 Palace Attendant Ping Dang of Pingling submitted a statement, \"The Grand Supreme Emperor is Han's founding ancestor—to abolish his temple park and garden is not right." },
  { zh: "」上亦以無繼嗣，遂納當言。", literal: "\" The emperor also, because there was no heir, thereupon accepted Dang's words.", idiomatic: "\" The emperor also, because there was no heir, thereupon accepted Dang's words." },
  { zh: "秋，九月，復太上皇寢廟園。", literal: "In autumn, the ninth month, the Grand Supreme Emperor's temple park and garden were restored.", idiomatic: "In autumn, the ninth month, the Grand Supreme Emperor's temple park and garden were restored." },
  { zh: "4　詔曰：「今大辟之刑千有餘條，律令煩多，百有餘萬言；", literal: "4 An edict said: \"Now the punishments of great execution are more than a thousand articles; statutes and ordinances are numerous and vexatious, more than a million words;", idiomatic: "4 An edict said, \"Now the punishments of great execution number more than a thousand articles; statutes and ordinances are numerous and vexatious, exceeding a million words;" },
  { zh: "奇請，它比，日以益滋。", literal: "special pleas and analogical comparisons daily grow more numerous.", idiomatic: "special pleas and analogical comparisons grow more numerous day by day." },
  { zh: "自明習者不知所由，欲以曉喻眾庶，不亦難乎！", literal: "Even those who understand clearly do not know whence they come—wishing to enlighten and instruct the masses, is it not difficult!", idiomatic: "Even those who understand clearly do not know whence they come—wishing to enlighten and instruct the masses, is it not difficult!" },
  { zh: "於以羅元元之民，夭絕亡辜，豈不哀哉！", literal: "Thereby to net the black-haired people, cut short the innocent without crime—is it not pitiable!", idiomatic: "Thereby to ensnare the common people and cut short the innocent without crime—is it not pitiable!" },
  { zh: "其議減死刑及可蠲除約省者，令較然易知，條奏！", literal: "Let them deliberate on reducing death penalties and what can be remitted, cut, and simplified, making it comparatively clear and easy to know—memorialize item by item!", idiomatic: "Let them deliberate on reducing death penalties and what can be remitted, cut, and simplified, making it comparatively clear and easy to know—memorialize item by item!" },
  { zh: "」時有司不能廣宣上意，徒鉤摭微細，毛舉數事，以塞詔而已。", literal: "\" At the time the responsible offices could not broadly proclaim the emperor's intent; they merely hooked and picked minute details, raised hairs and cited a few matters, to satisfy the edict and nothing more.", idiomatic: "\" At the time the responsible offices could not broadly proclaim the emperor's intent; they merely picked minute details, cited a few matters, and satisfied the edict and nothing more." },
  { zh: "----5　匈奴單于遣右皋林王伊邪莫演等奉獻，朝正月。", literal: "----5 The Xiongnu chanyu sent the Right Gao-lin King Yi Yemo Yan and others to present tribute and attend court at the first month.", idiomatic: "----5 The Xiongnu chanyu sent the Right Gao-lin King Yi Yemo Yan and others to present tribute and attend court at the first month." },
  { zh: "1　春，伊邪莫演罷歸，自言欲降：「即不受我，我自殺，終不敢還歸。", literal: "1 In spring, Yi Yemo Yan, dismissed and returning, said himself he wished to surrender: \"If you do not accept me, I will kill myself—I ultimately dare not return.", idiomatic: "1 In spring, Yi Yemo Yan, dismissed and returning, said he wished to surrender: \"If you do not accept me, I will kill myself—I ultimately dare not return." },
  { zh: "」使者以聞，下公卿議。", literal: "\" The envoy reported it; it was sent down to the grandees for deliberation.", idiomatic: "\" The envoy reported it; it was sent down to the grandees for deliberation." },
  { zh: "議者或言：「宜如故事，受其降。", literal: "Some who deliberated said: \"It is fitting to follow precedent and accept his surrender.", idiomatic: "Some who deliberated said, \"It is fitting to follow precedent and accept his surrender." },
  { zh: "」光祿大夫谷永、議郎杜欽以為：「漢興，匈奴數為邊害，故設金爵之賞以待降者。", literal: "\" Grand Master of Splendor Gu Yong and Consultant Gentleman Du Qin held: \"Since Han arose, the Xiongnu repeatedly harmed the borders, and therefore a reward of golden wine-cups was established to await those who surrendered.", idiomatic: "\" Grand Master of Splendor Gu Yong and Consultant Gentleman Du Qin argued, \"Since Han arose, the Xiongnu repeatedly harmed the borders, and therefore a reward of golden wine-cups was established to await those who surrendered." },
  { zh: "今單于屈體稱臣，列為北籓，遣使朝賀，無有二心。", literal: "Now the chanyu bends his person and styles himself subject, ranks as northern vassal, sends envoys to attend court and offer congratulations, and has no second heart.", idiomatic: "Now the chanyu bends his person and styles himself subject, ranks as a northern vassal, sends envoys to attend court and offer congratulations, and has no second heart." },
  { zh: "漢家接之，宜異於往時。", literal: "Han in receiving him ought to differ from former times.", idiomatic: "Han in receiving him ought to differ from former times." },
  { zh: "今既享單于聘貢之質，而更受其逋逃之臣，是貪一夫之得而失一國之心，擁有罪之臣而絕慕義之君也。", literal: "Now having already enjoyed the chanyu's tribute gifts, yet again to accept his fugitive fleeing subjects is to be greedy for one man's gain and lose one state's heart, to embrace a guilty subject and cut off a lord who admires righteousness.", idiomatic: "Now having already enjoyed the chanyu's tribute gifts, yet again to accept his fugitive subjects is to be greedy for one man's gain and lose an entire state's goodwill, to embrace a guilty subject and cut off a lord who admires righteousness." },
  { zh: "假令單于初立，欲委身中國，未知利害，私使伊邪莫演詐降以卜吉凶，受之，虧德沮善，令單于自疏，不親邊吏；", literal: "Suppose the chanyu had just taken the throne, wished to commit his person to the Middle Kingdom, did not yet know benefit and harm, and privately sent Yi Yemo Yan to feign surrender to divine good and ill—if accepted, it would diminish virtue and discourage goodness, making the chanyu distance himself and not be close to border officials;", idiomatic: "Suppose the chanyu had just taken the throne, wished to commit himself to the Middle Kingdom, did not yet know benefit and harm, and privately sent Yi Yemo Yan to feign surrender to divine good and ill—if accepted, it would diminish virtue and discourage goodwill, making the chanyu distance himself and not be close to border officials;" },
  { zh: "或者設為反間，欲因而生隙，受之，適合其策，使得歸曲而責直。", literal: "or perhaps he set up a counter-stratagem, wishing thereby to create a rift—if accepted, it would exactly fit his plan, enabling him to return the crooked and blame the straight.", idiomatic: "or perhaps he set up a counter-stratagem, wishing thereby to create a rift—if accepted, it would exactly fit his plan, enabling him to turn the blame back on the righteous party." },
  { zh: "此誠邊境安危之原，師旅動靜之首，不可不詳也。", literal: "This truly is the source of border safety and peril, the head of army movement and stillness—it cannot but be examined in detail.", idiomatic: "This truly is the source of border safety and peril, the head of military movement and stillness—it must be examined in detail." },
  { zh: "不如勿受，以昭日月之信，抑詐諼之謀，懷附親之心，便！", literal: "It is better not to accept, to display the faith of sun and moon, suppress deceitful and clamorous plots, cherish hearts that attach in kinship—convenient!", idiomatic: "It is better not to accept, to display the faith of sun and moon, suppress deceitful plots, and cherish hearts that attach in kinship—convenient!" },
  { zh: "」對奏，天子從之。", literal: "\" They replied and memorialized; the Son of Heaven followed it.", idiomatic: "\" They replied and memorialized; the emperor followed it." },
  { zh: "遣中郎將王舜往問降狀，伊邪莫演曰：「我病狂，妄言耳。", literal: "He dispatched Palace Gentleman Wang Shun to go inquire into the surrender's circumstances; Yi Yemo Yan said: \"I was mad with illness—empty words only.", idiomatic: "He dispatched Palace Gentleman Wang Shun to inquire into the surrender; Yi Yemo Yan said, \"I was mad with illness—empty words only." },
  { zh: "」遣去。", literal: "\" He was sent away.", idiomatic: "\" He was sent away." },
  { zh: "歸到，官位如故，不肯令見漢使。", literal: "When he returned, his office and rank were as before; he would not allow him to see Han envoys.", idiomatic: "When he returned, his office and rank were as before; the chanyu would not allow him to see Han envoys." },
  { zh: "----2　夏，四月，楚國雨雹，大如釜。", literal: "----2 In summer, the fourth month, Chu had rain of hailstones as large as cauldrons.", idiomatic: "----2 In summer, the fourth month, Chu had hail as large as cauldrons." },
  { zh: "----3　徙山陽王康為定陶王。", literal: "----3 Prince Kang of Shanyang was moved to be Prince of Dingtao.", idiomatic: "----3 Prince Kang of Shanyang was moved to be Prince of Dingtao." },
  { zh: "----4　六月，上悉封諸舅：王譚為平阿侯，商為成都侯，立為紅陽侯，根為曲陽侯，逢時為高平侯。", literal: "----4 In the sixth month, the emperor enfeoffed all his maternal uncles: Wang Tan as Marquis of Ping'a, Shang as Marquis of Chengdu, Li as Marquis of Hongyang, Gen as Marquis of Quyang, Fengshi as Marquis of Gaoping.", idiomatic: "----4 In the sixth month, the emperor enfeoffed all his maternal uncles: Wang Tan as Marquis of Ping'a, Shang as Marquis of Chengdu, Li as Marquis of Hongyang, Gen as Marquis of Quyang, and Fengshi as Marquis of Gaoping." },
  { zh: "五人同日封，故世謂之「五侯」。", literal: "The five men were enfeoffed on the same day; therefore the age calls them the \"Five Marquises.\"", idiomatic: "The five men were enfeoffed on the same day; therefore the age calls them the \"Five Marquises.\"" },
  { zh: "太后母李氏更嫁為河內苟賓妻，生子參；", literal: "The empress dowager's mother Lady Li remarried to become wife of Gou Bin of Henei and bore a son Can;", idiomatic: "The empress dowager's mother Lady Li remarried to become the wife of Gou Bin of Henei and bore a son, Can;" },
  { zh: "太后欲以田□分為比而封之。", literal: "the empress dowager wished to take Tian □'s fief as comparison and enfeoff him.", idiomatic: "the empress dowager wished to grant a fief comparable to Tian □'s and enfeoff him." },
  { zh: "上曰：「封田氏，非正也。", literal: "The emperor said: \"To enfeoff the Tian clan is not correct.", idiomatic: "The emperor said, \"To enfeoff the Tian clan is not correct." },
  { zh: "」以參為侍中、水衡都尉。", literal: "\" He made Can Attendant-in-Ordinary and Commandant of the Palace Parks.", idiomatic: "\" He made Can Attendant-in-Ordinary and Commandant of the Palace Parks." },
  { zh: "----5　御史大夫張忠奏京兆尹王尊暴虐倨慢，尊坐免官；", literal: "----5 Censor-in-Chief Zhang Zhong memorialized that Metropolitan Magistrate Wang Zun was brutal, cruel, arrogant, and insolent; Zun was punished by dismissal from office;", idiomatic: "----5 Censor-in-Chief Zhang Zhong memorialized that Metropolitan Magistrate Wang Zun was brutal, cruel, arrogant, and insolent; Zun was dismissed from office;" },
  { zh: "吏民多稱惜之。", literal: "officials and common people mostly praised and regretted it.", idiomatic: "officials and common people mostly praised and regretted it." },
  { zh: "湖三老公乘興等上書訟：「尊治京兆，撥劇整亂，誅暴禁邪，皆前所稀有，名將所不及；", literal: "The three elders of Hu, Gongcheng Xing and others, submitted a memorial in his defense: \"Zun governed the metropolitan region, pulled apart the acute and set disorder in order, punished the violent and forbade evil—all were rare before, what famous generals did not reach;", idiomatic: "The three elders of Hu, Gongcheng Xing and others, submitted a memorial in his defense: \"Zun governed the metropolitan region, pulled apart acute crises and set disorder in order, punished the violent and forbade evil—all were rare before, beyond what famous generals achieved;" },
  { zh: "雖拜為真，未有殊絕褒賞加於尊身。", literal: "though appointed to the true post, there was no extraordinary reward and praise added to Zun's person.", idiomatic: "though appointed to the true post, no extraordinary reward and praise was added to Zun's person." },
  { zh: "今御史大夫奏尊『傷害陰陽，為國家憂，無承用詔書意，『靖言庸違，像龔滔天。", literal: "Now the censor-in-chief memorializes that Zun 'injures yin and yang, brings worry to the state, does not carry out the edict's intent,' 'speaks quietly yet perversely violates, imitates Gong and floods Heaven.", idiomatic: "Now the censor-in-chief memorializes that Zun 'injures yin and yang, brings worry to the state, does not carry out the edict's intent,' 'speaks quietly yet perversely violates, imitates Gong and floods Heaven." },
  { zh: "』」源其所以，出御史丞楊輔，素與尊有私怨，外依公事建畫為此議，傅致奏文，浸潤加誣，臣等竊痛傷。", literal: "'\" Tracing its cause, it came from Vice Censor Yang Fu, who from of old had a private grudge with Zun; outwardly relying on public business he drafted and plotted this opinion, attached and led the memorial text, and by gradual soaking added slander—your subjects secretly are pained and wounded.", idiomatic: "'\" Tracing its cause, it came from Vice Censor Yang Fu, who from of old had a private grudge with Zun; outwardly relying on public business he drafted this opinion, attached and led the memorial text, and by gradual insinuation added slander—your subjects are secretly pained." },
  { zh: "尊修身潔己，砥節首公，刺譏不憚將相，誅惡不避豪強，誅不制之賊，解國家之憂，功著職修，威信不廢，誠國家爪牙之吏，折衝之臣。", literal: "Zun cultivated his person and cleansed himself, whetted his integrity and put the public first, satirized and reproached without fearing generals and chancellors, punished evil without avoiding the powerful and strong, executed uncontrolled bandits, removed the state's worry—merit was manifest, office was well kept, authority and trust were not abandoned; he truly was the state's claw-and-fang official, a minister who repelled the foe.", idiomatic: "Zun cultivated his person and cleansed himself, whetted his integrity and put the public first, satirized and reproached without fearing generals and chancellors, punished evil without avoiding the powerful, executed uncontrolled bandits, and removed the state's worry—merit was manifest, office was well kept, authority and trust were not abandoned; he truly was the state's claw-and-fang officer, a minister who repelled the foe." },
  { zh: "今一旦無辜制於仇人之手，傷於詆欺之文，上不得以功除罪，下不得蒙棘木之聽，獨掩怨讎之偏奏，被共工之大惡，無所陳冤訴罪。", literal: "Now in a single morning, innocent, he is controlled by an enemy's hand, wounded by calumny and deceit's text—above he cannot use merit to remove guilt, below he cannot receive the hearing of thorn-wood; alone he is covered by a partial memorial of resentful foe, bears Gong Gong's great evil, and has nowhere to state wrong and plead guilt.", idiomatic: "Now in a single morning, innocent, he is controlled by an enemy's hand, wounded by calumny and deceit—above he cannot use merit to remove guilt, below he cannot receive a fair hearing; alone he is covered by a partial memorial of a resentful foe, bears Gong Gong's great evil, and has nowhere to state his case." },
  { zh: "尊以京師廢亂，群盜並興，選賢徵用，起家為卿。", literal: "Zun, because the capital was ruined and chaotic and bandits rose together, was selected as worthy and summoned to employment, rising from his house to be a minister.", idiomatic: "Because the capital was ruined and chaotic and bandits rose together, Zun was selected as worthy and summoned to office, rising from his house to ministerial rank." },
  { zh: "賊亂既除，豪猾伏辜，即以佞巧廢黜。", literal: "Once bandit disorder was removed and powerful scoundrels submitted to punishment, he was at once dismissed through flattery and craft.", idiomatic: "Once bandit disorder was removed and powerful scoundrels submitted to punishment, he was at once dismissed through flattery and craft." },
  { zh: "一尊之身，三期之間，乍賢乍佞，豈不甚哉！", literal: "For one man Zun's person, within three terms, now worthy now crafty—is it not extreme!", idiomatic: "For one man, within three terms, now worthy now crafty—is it not extreme!" },
  { zh: "孔子曰：『愛之欲其生，惡之欲其死，是惑也。", literal: "Confucius said: 'To love him and wish him to live, to hate him and wish him to die—this is delusion.", idiomatic: "Confucius said, 'To love him and wish him to live, to hate him and wish him to die—this is delusion." },
  { zh: "』『浸潤之譖不行焉，可謂明矣。", literal: "' 'If gradual soaking slander does not proceed, one may be called clear-sighted.", idiomatic: "' 'If gradual insinuating slander does not proceed, one may be called clear-sighted." },
  { zh: "』願下公卿、大夫、博士、議郎定尊素行！", literal: "' We wish Your Majesty to send it down to grandees, great officers, erudites, and consultant gentlemen to fix Zun's constant conduct!", idiomatic: "' We wish Your Majesty to send it down to grandees, great officers, erudites, and consultant gentlemen to determine Zun's constant conduct!" },
  { zh: "夫人臣而『傷害陰陽』，死誅之罪也；", literal: "For a subject-minister to 'injure yin and yang' is a crime punishable by death;", idiomatic: "For a subject-minister to 'injure yin and yang' is a crime punishable by death;" },
  { zh: "『靖言庸違』，放殛之刑也。", literal: "'to speak quietly yet perversely violate' is a punishment of exile and execution.", idiomatic: "'to speak quietly yet perversely violate' is a punishment of exile and execution." },
  { zh: "審如御史章，尊乃當伏觀闕之誅，放於無人之域，不得苟免；", literal: "If truly like the censor's memorial, Zun ought to submit to execution before the gate tower, be cast into a realm without men, and not obtain careless exemption;", idiomatic: "If truly like the censor's memorial, Zun ought to submit to execution before the gate tower, be cast into a realm without men, and obtain no careless exemption;" },
  { zh: "及任舉尊者，當獲選舉之辜，不可但已。", literal: "and those who recommended and raised Zun ought to receive the guilt of selection—they cannot merely stop.", idiomatic: "and those who recommended and raised Zun ought to receive the guilt of selection—they cannot merely stop." },
  { zh: "即不如章，飾文深詆以訴無罪，亦宜有誅，以懲讒賊之口，絕詐欺之路。", literal: "If it is not like the memorial, to adorn text and deeply slander to plead innocence, there also ought to be punishment, to chastise the mouths of slanderous villains and cut off the road of deceit and fraud.", idiomatic: "If it is not like the memorial, to adorn text and deeply slander to plead innocence, there also ought to be punishment, to chastise slanderous mouths and cut off the road of deceit." },
  { zh: "唯明主參詳，使白黑分別！", literal: "Only the enlightened ruler examine in detail and make white and black distinct!", idiomatic: "Only the enlightened ruler will examine in detail and make right and wrong distinct!" },
  { zh: "」書奏，天子復以尊為徐州刺史。", literal: "\" The memorial was submitted; the Son of Heaven again made Zun Regional Inspector of Xuzhou.", idiomatic: "\" The memorial was submitted; the emperor again made Zun Regional Inspector of Xuzhou." },
  { zh: "----6　夜郎王興、金句町王禹、漏臥侯俞更舉兵相攻。", literal: "----6 The king of Yelang Xing, the king of Jinjuding Yu, and Marquis Louwo Yu again raised troops and attacked one another.", idiomatic: "----6 The king of Yelang Xing, the king of Jinjuding Yu, and Marquis Louwo Yu again raised troops and attacked one another." },
  { zh: "牂柯太守請發兵誅興等。", literal: "The Administrator of Zangke requested to dispatch troops to execute Xing and the rest.", idiomatic: "The Administrator of Zangke requested to dispatch troops to execute Xing and the rest." },
  { zh: "議者以為道遠不可擊，乃遣太中大夫蜀郡張匡持節和解。", literal: "Those who deliberated held the road was distant and they could not be struck; they therefore dispatched Grand Master of the Palace Zhang Kuang of Shu Commandery, bearing credentials, to reconcile.", idiomatic: "Those who deliberated held the road was distant and they could not be struck; they therefore dispatched Grand Master of the Palace Zhang Kuang of Shu Commandery, bearing credentials, to reconcile." },
  { zh: "興等不從命，刻木象漢吏，立道旁，射之。", literal: "Xing and the rest did not obey the command; they carved wood in the likeness of Han officials, set them beside the road, and shot them.", idiomatic: "Xing and the rest did not obey the command; they carved wooden images of Han officials, set them beside the road, and shot them." },
  { zh: "杜欽說大將軍王鳳曰：「蠻夷王侯輕易漢使，不憚國威，恐議者選耎，復守和解；", literal: "Du Qin advised the Grand General Wang Feng, saying: \"Barbarian kings and marquises lightly treat Han envoys and do not fear the state's majesty—I fear deliberators will be chosen soft and again hold to reconciliation;", idiomatic: "Du Qin advised the Grand General Wang Feng, saying, \"Barbarian kings and marquises lightly treat Han envoys and do not fear the state's majesty—I fear deliberators will be chosen soft and again hold to reconciliation;" },
  { zh: "太守察動靜有變，乃以聞。", literal: "the administrator observes movement and stillness and there is change, and only then reports it.", idiomatic: "the administrator observes movement and stillness and there is change, and only then reports it." },
  { zh: "如此，則復曠一時，王侯得收獵其眾，申固其謀，黨助眾多，各不勝忿，必相殄滅。", literal: "If so, again a season will be wasted; kings and marquises will be able to gather and hunt their masses, renew and solidify their plots, partisan helpers will be many, each unable to overcome rage—they are sure to destroy one another.", idiomatic: "If so, again a season will be wasted; kings and marquises will gather and hunt their followers, renew and solidify their plots, partisan helpers will multiply, each unable to overcome rage—they are sure to destroy one another." },
  { zh: "自知罪成，狂犯守尉，遠臧溫暑毒草之地；", literal: "Knowing their guilt is complete, they will madly offend the commandery and county officials and hide far in warm, hot, poisonous-grass lands;", idiomatic: "Knowing their guilt is complete, they will madly offend the commandery and county officials and hide far in warm, hot, poisonous-grass lands;" },
  { zh: "雖有孫、吳將，賁、育士，若入水火，往必焦沒，智勇亡所施。", literal: "though there were generals like Sun and Wu, warriors like Ben and Yu, as if entering fire and water, going they would surely be scorched and drowned—wisdom and courage would have nowhere to deploy.", idiomatic: "though there were generals like Sun and Wu, warriors like Ben and Yu, as if entering fire and water, going they would surely be scorched and drowned—wisdom and courage would have nowhere to deploy." },
  { zh: "屯田守之，費不可勝量。", literal: "Garrison-farming to hold them—the expense cannot be measured.", idiomatic: "Garrison-farming to hold them—the expense cannot be measured." },
  { zh: "宜因其罪惡未成，未疑漢家加誅，陰敕旁郡守尉練士馬，大司農豫調谷積要害處，選任職太守往。", literal: "It is fitting, while their guilt and evil are not yet complete and they do not yet suspect Han will add execution, secretly to order neighboring commanderies' administrators and county officials to drill soldiers and horses, have the Grand Minister of Agriculture beforehand transfer grain and store it at strategic points, and select a competent administrator to go.", idiomatic: "It is fitting, while their guilt is not yet complete and they do not yet suspect Han will add execution, secretly to order neighboring commanderies' administrators and county officials to drill soldiers and horses, have the Grand Minister of Agriculture beforehand transfer grain and store it at strategic points, and select a competent administrator to go." },
  { zh: "以秋涼時入，誅其王侯尤不軌者。", literal: "Enter in the cool of autumn and execute the kings and marquises who are especially lawless.", idiomatic: "Enter in the cool of autumn and execute the kings and marquises who are especially lawless." },
  { zh: "即以為不毛之地，無用之民，聖王不以勞中國，宜罷郡，放棄其民，絕其王侯勿復通。", literal: "Then regard it as unproductive land and useless people—the sage king does not weary the Middle Kingdom; it is fitting to abolish the commandery, abandon its people, and cut off its kings and marquises—do not communicate again.", idiomatic: "Then regard it as unproductive land and useless people—the sage king does not weary the Middle Kingdom; it is fitting to abolish the commandery, abandon its people, and cut off its kings and marquises—do not communicate again." },
  { zh: "如以先帝所立累世之功不可墮壞，亦宜因其萌牙，早斷絕之。", literal: "If because the successive generations' achievement established by the former emperor cannot be cast down and ruined, it is also fitting, while their first sprouts remain, early to cut them off.", idiomatic: "If because the successive generations' achievement established by the former emperor cannot be cast down and ruined, it is also fitting, while their first sprouts remain, to cut them off early." },
  { zh: "及已成形然後戰師，則萬姓被害。", literal: "If after they have already taken form one then battles with troops, then the myriad people will suffer harm.", idiomatic: "If after they have already taken form one then battles with troops, the myriad people will suffer harm." },
  { zh: "」大將軍鳳於是薦金城司馬臨邛陳立為牂柯太守。", literal: "\" The Grand General Feng thereupon recommended Chen Li of Linqiong, Major of Jincheng, as Administrator of Zangke.", idiomatic: "\" The Grand General Feng thereupon recommended Chen Li of Linqiong, Major of Jincheng, as Administrator of Zangke." },
  { zh: "立至牂柯，諭告夜郎王興，興不從命；", literal: "When Li reached Zangke, he announced and instructed the king of Yelang Xing; Xing did not obey the command;", idiomatic: "When Li reached Zangke, he announced and instructed the king of Yelang Xing; Xing did not obey the command;" },
  { zh: "立請誅之，未報。", literal: "Li requested to execute him; there was no reply.", idiomatic: "Li requested to execute him; there was no reply." },
  { zh: "乃從吏數十人出行縣，至興國且同亭，召興。", literal: "He thereupon took several tens of clerks and went out on a tour of the county, reaching Xing's state at Qietong Pavilion, and summoned Xing.", idiomatic: "He thereupon took several tens of clerks and went out on a tour of the county, reaching Xing's state at Qietong Pavilion, and summoned Xing." },
  { zh: "興將數千人往至亭，從邑君數十人入見立。", literal: "Xing led several thousand men and went to the pavilion; with several tens of district lords he entered to see Li.", idiomatic: "Xing led several thousand men to the pavilion; with several tens of district lords he entered to see Li." },
  { zh: "立數責，因斷頭。", literal: "Li repeatedly reproached him and thereupon cut off his head.", idiomatic: "Li repeatedly reproached him and thereupon cut off his head." },
  { zh: "邑君曰：「將軍誅無狀，為民除害，願出曉士眾！", literal: "The district lord said: \"The general executed the lawless one and removed harm for the people—I wish to go out and enlighten the soldiers and masses!", idiomatic: "The district lord said, \"The general executed the lawless one and removed harm for the people—I wish to go out and enlighten the soldiers and masses!" },
  { zh: "」以興頭示之，皆釋兵降。", literal: "\" He displayed Xing's head to them; all laid down arms and surrendered.", idiomatic: "\" He displayed Xing's head to them; all laid down arms and surrendered." },
  { zh: "金句町王禹、漏臥侯俞震恐，入粟千斛、牛羊勞吏士。", literal: "The king of Jinjuding Yu and Marquis Louwo Yu were shaken with fear and sent in a thousand piculs of grain and cattle and sheep to comfort officials and soldiers.", idiomatic: "The king of Jinjuding Yu and Marquis Louwo Yu were shaken with fear and sent in a thousand piculs of grain and cattle and sheep to comfort officials and soldiers." },
  { zh: "立還歸郡。", literal: "Li returned to the commandery.", idiomatic: "Li returned to his commandery." },
  { zh: "興妻父翁指，與子邪務收餘兵，迫脅旁二十二邑反。", literal: "Xing's wife's father Weng Zhi, with his son Xie Wu, gathered the remaining soldiers, coerced the twenty-two neighboring districts, and rebelled.", idiomatic: "Xing's father-in-law Weng Zhi, with his son Xie Wu, gathered the remaining troops, coerced twenty-two neighboring districts, and rebelled." },
  { zh: "至冬，立奏募諸夷，與都尉、長史分將攻翁指等。", literal: "By winter, Li memorialized to recruit the various Yi, and with the commandant and chief clerk separately led attacks on Weng Zhi and the rest.", idiomatic: "By winter Li memorialized to recruit the various Yi peoples, and he and the commandant and chief clerk led separate forces to attack Weng Zhi and the rest." },
  { zh: "翁指據厄為壘，立使奇兵絕其饟道，縱反間以誘其眾。", literal: "Weng Zhi held a narrow pass and made fortifications; Li sent irregular troops to cut off his supply route and spread disinformation to lure his masses.", idiomatic: "Weng Zhi held a narrow pass and built fortifications. Li sent irregular troops to cut off his supply lines and spread disinformation to lure his followers." },
  { zh: "都尉萬年曰：「兵久不決，費不可共。", literal: "Commandant Wannian said: \"The troops have long been unable to decide the issue; the expense cannot be borne together.", idiomatic: "Commandant Wannian said, \"The campaign has dragged on without decision; the expense cannot be borne jointly." },
  { zh: "」引兵獨進。", literal: "\" He led his troops forward alone.", idiomatic: "\" He led his troops forward alone." },
  { zh: "敗走，趨立營。", literal: "Defeated, he fled and rushed toward Li's camp.", idiomatic: "Defeated, he fled toward Li's camp." },
  { zh: "立怒，叱戲下令格之。", literal: "Li was angry, reproached the guards, and ordered them to stop him.", idiomatic: "Li was furious, reproached the guards, and ordered them to bar his entry." },
  { zh: "都尉復還戰，立救之。", literal: "The commandant returned to battle again, and Li rescued him.", idiomatic: "The commandant returned to battle again, and Li rescued him." },
  { zh: "時天大旱，立攻絕其水道。", literal: "At the time there was great drought; Li attacked and cut off their water supply.", idiomatic: "At the time there was a severe drought; Li attacked and cut off their water supply." },
  { zh: "蠻夷共斬翁指，持首出降，西夷遂平。", literal: "The barbarian Yi together beheaded Weng Zhi, brought out his head and surrendered, and the western Yi were thereby pacified.", idiomatic: "The Yi together beheaded Weng Zhi, presented his head, and surrendered; the western Yi were thereby pacified." },
  { zh: "1　春，正月，楚王囂來朝。", literal: "1 In spring, the first month, the King of Chu Xiao came to court.", idiomatic: "1 In spring, the first month, King Xiao of Chu came to court." },
  { zh: "二月，乙亥，詔以囂素行純茂，特加顯異，封其子勳為廣戚侯。", literal: "Second month, on yihai, an edict held that because Xiao's conduct had always been pure and abundant, he was specially granted outstanding distinction, and his son Xun was enfeoffed as Marquis of Guangqi.", idiomatic: "In the second month, on yihai, an edict noted that Xiao's conduct had always been pure and exemplary, granted him special distinction, and enfeoffed his son Xun as Marquis of Guangqi." },
  { zh: "----2　丙戌，犍為地震，山崩，壅江水，水逆流。", literal: "----2 On bingxu, Jianwei had an earthquake; mountains collapsed, blocked the Yangzi River, and the water flowed backward.", idiomatic: "----2 On bingxu, Jianwei suffered an earthquake; mountains collapsed, blocked the Yangzi, and the river flowed backward." },
  { zh: "----3　秋，八月，乙卯晦，日有食之。", literal: "----3 In autumn, the eighth month, on the last day of the cycle yimao, there was a solar eclipse.", idiomatic: "----3 In autumn, the eighth month, on the last day of yimao, there was a solar eclipse." },
  { zh: "----4　上以中秘書頗散亡，使謁者陳農求遺書於天下。", literal: "----4 The emperor, because the palace secretariat books had largely been scattered and lost, sent Palace Attendant Chen Nong to seek lost books throughout the realm.", idiomatic: "----4 Because many books in the palace secretariat had been lost, the emperor sent Palace Attendant Chen Nong to seek lost books throughout the realm." },
  { zh: "詔光祿大夫劉向校經傳、諸子、詩賦，步兵校尉任宏校兵書，太史令尹鹹校數術，侍醫李柱國校方技。", literal: "An edict ordered Household Grandee Liu Xiang to collate the classics and commentaries, the masters, and poetry and rhapsodies; Commandant of Foot Soldiers Ren Hong to collate military books; Grand Astrologer Yin Xian to collate numerology; and Attending Physician Li Zhuguo to collate occult arts.", idiomatic: "An edict ordered Household Grandee Liu Xiang to collate the classics, masters, and poetry; Commandant of Foot Soldiers Ren Hong to collate military texts; Grand Astrologer Yin Xian to collate numerology; and Attending Physician Li Zhuguo to collate technical and occult works." },
  { zh: "每一書已，向輒條其篇目，撮其指意，錄而奏之。", literal: "Whenever one book was finished, Xiang would itemize its chapters and sections, extract its main purport, record it, and submit it.", idiomatic: "Whenever a book was finished, Xiang itemized its chapters, summarized its main purport, recorded it, and submitted it to the throne." },
  { zh: "劉向以王氏權位太盛，而上方向《詩》、《書》古文，向乃因《尚書‧洪範》，集合上古以來，歷春秋、六國至秦、漢符瑞、災異之記，推跡行事，連傅禍福，著其占驗，比類相從，各有條目，凡十一篇，號曰《洪範五行傳論》，奏之。", literal: "Liu Xiang, because the Wang clan's power and position were too great and the emperor inclined toward the ancient texts of the Odes and Documents, thereupon drew on the Hongfan section of the Documents, gathering records of omens and strange events from high antiquity through Spring and Autumn, the Six States, and Qin and Han, tracing deeds and linking blessings and calamities, setting forth their prognostications, arranging them by category each with its own entries—eleven sections in all, titled Treatise on the Five Phases of the Hongfan—and submitted it.", idiomatic: "Liu Xiang, seeing the Wang clan's power as too great and knowing the emperor favored the ancient texts of the Odes and Documents, drew on the Hongfan section of the Documents and gathered records of omens and disasters from antiquity through Spring and Autumn, the Warring States, and Qin and Han. He traced deeds and linked blessings and calamities, set forth their prognostications, and arranged them by category into eleven sections titled Treatise on the Five Phases of the Hongfan, which he submitted." },
  { zh: "天子心知向忠精，故為鳳兄弟起此論也；", literal: "The Son of Heaven knew in his heart that Xiang was loyal and earnest and that this treatise was therefore raised for the Feng brothers' sake;", idiomatic: "The emperor knew in his heart that Xiang was loyal and earnest and that this treatise was raised for the Feng brothers' sake;" },
  { zh: "然終不能奪王氏權。", literal: "yet in the end he could not wrest power from the Wang clan.", idiomatic: "yet in the end he could not wrest power from the Wang clan." },
  { zh: "----5　河復決平原，流入濟南、千乘，所壞敗者半建始時。", literal: "----5 The Yellow River again burst its banks in Pingyuan and flowed into Jinan and Qiancheng; what was destroyed and ruined was half as much as in the Jianshi period.", idiomatic: "----5 The Yellow River again burst its banks in Pingyuan and flowed into Jinan and Qiancheng; the damage was half what it had been in the Jianshi period." },
  { zh: "復遣王延世與丞相史楊焉及將作大匠許商、諫大夫乘馬延年同作治，六月乃成。", literal: "He again sent Wang Yanshi with the chancellor's clerk Yang Yan and Chief Artisan for Palace Construction Xu Shang and Remonstrance Grandee Chengmayan Nian to work on repairs together; after six months it was completed.", idiomatic: "He again sent Wang Yanshi with the chancellor's clerk Yang Yan, Chief Artisan for Palace Construction Xu Shang, and Remonstrance Grandee Chengmayan Nian to repair it together; after six months the work was finished." },
  { zh: "復賜延世黃金百斤。", literal: "Yanshi was again granted a hundred jin of gold.", idiomatic: "Yanshi was again granted a hundred jin of gold." },
  { zh: "治河卒非受平賈者，為著外繇六月。", literal: "River-work corvée soldiers who had not received the fair price were recorded for six months of external corvée.", idiomatic: "River workers who had not received fair payment were credited with six months of external corvée service." },
  { zh: "1　春，正月，匈奴單于來朝。", literal: "1 In spring, the first month, the Xiongnu chanyu came to court.", idiomatic: "1 In spring, the first month, the Xiongnu chanyu came to court." },
  { zh: "----2　赦天下徒。", literal: "----2 There was an amnesty for convict laborers throughout the realm.", idiomatic: "----2 There was an amnesty for convict laborers throughout the realm." },
  { zh: "----3　三月，癸丑朔，日有食之。", literal: "----3 Third month, on the first day of the cycle guichou, there was a solar eclipse.", idiomatic: "----3 In the third month, on the first day of guichou, there was a solar eclipse." },
  { zh: "----4　琅邪太守楊肜與王鳳連昏，其郡有災害，丞相王商按問之。", literal: "----4 Administrator of Langye Yang Tong was allied by marriage with Wang Feng; his commandery had disasters and calamities, and Chancellor Wang Shang investigated and questioned him.", idiomatic: "----4 Administrator of Langye Yang Tong was allied by marriage with Wang Feng. His commandery suffered disasters, and Chancellor Wang Shang investigated him." },
  { zh: "鳳以為請，商不聽，竟奏免肜，奏果寢不下。", literal: "Feng pleaded on his behalf; Shang would not listen and in the end memorialized to dismiss Tong; the memorial was indeed shelved and not issued.", idiomatic: "Feng pleaded on his behalf, but Shang refused and eventually memorialized to dismiss Tong; the memorial was shelved and never issued." },
  { zh: "鳳以是怨商，陰求其短，使頻陽耿定上書，言「商與父傅婢通；", literal: "Feng therefore resented Shang, secretly sought his faults, and had Geng Ding of Pinyang submit a memorial saying, \"Shang had relations with his father's servant girl;", idiomatic: "Feng therefore resented Shang, secretly sought his faults, and had Geng Ding of Pinyang submit a memorial saying, \"Shang had relations with his father's servant girl;" },
  { zh: "及女弟淫亂，奴殺其私夫，疑商教使。", literal: "and his younger sister was licentious; a slave killed her paramour, and it was suspected Shang had instructed it.", idiomatic: "and his younger sister was licentious; a slave killed her paramour, and Shang was suspected of having instigated it." },
  { zh: "」天子以為暗昧之過，不足以傷大臣。", literal: "\" The Son of Heaven held that these were obscure and hidden faults, insufficient to harm a great minister.", idiomatic: "\" The emperor held that these were obscure private faults, insufficient to harm a great minister." },
  { zh: "鳳固爭，下其事司隸。", literal: "Feng firmly pressed the point, and the matter was sent down to the Director of Justice.", idiomatic: "Feng pressed the point firmly, and the matter was referred to the Director of Justice." },
  { zh: "太中大夫蜀郡張匡，素佞巧，復上書極言詆毀商。", literal: "Grand Master of Splendor Zhang Kuang of Shu commandery, by nature fawning and crafty, again submitted a memorial vehemently slandering Shang.", idiomatic: "Grand Master of Splendor Zhang Kuang of Shu, by nature fawning and crafty, again submitted a memorial vehemently slandering Shang." },
  { zh: "有司奏請召商詣詔獄。", literal: "The relevant offices memorialized requesting that Shang be summoned to the imperial prison.", idiomatic: "The relevant offices memorialized requesting that Shang be summoned to the imperial prison." },
  { zh: "上素重商，知匡言多險，制曰：「勿治！", literal: "The emperor had always valued Shang, knew Kuang's words were mostly dangerous, and ordered: \"Do not prosecute!", idiomatic: "The emperor had always valued Shang and knew Kuang's words were mostly malicious. He ordered, \"Do not prosecute!" },
  { zh: "」鳳固爭之。", literal: "\" Feng firmly pressed the matter.", idiomatic: "\" Feng pressed the matter firmly." },
  { zh: "夏，四月，壬寅，詔收商丞相印綬。", literal: "Summer, fourth month, on renyin, an edict ordered the seizure of Shang's chancellor seal and ribbon.", idiomatic: "In summer, the fourth month, on renyin, an edict ordered Shang's chancellor seal and ribbon seized." },
  { zh: "商免相三日，發病，歐血薨，謚曰戾侯。", literal: "Three days after Shang was dismissed as chancellor he fell ill, vomited blood, and died; his posthumous title was Marquis Li.", idiomatic: "Three days after Shang was dismissed as chancellor he fell ill, vomited blood, and died; his posthumous title was Marquis Li." },
  { zh: "而商子弟親屬為駙馬都尉、侍中、中常侍、諸曹、大夫、郎吏者，皆出補吏，莫得留給事、宿衛者。", literal: "Shang's sons, younger brothers, and kin who served as Commandant of Equipage, Palace Attendant, Palace Regular Attendant, various bureau posts, grandees, and gentleman-officials were all sent out to fill outside posts and none were allowed to remain in attendance or palace guard duty.", idiomatic: "Shang's sons, brothers, and kin who held posts as Commandant of Equipage, Palace Attendant, Palace Regular Attendant, bureau offices, grandees, or gentleman-officials were all sent out to provincial posts; none were allowed to remain in attendance or palace guard duty." },
  { zh: "有司奏請除國邑；", literal: "The relevant offices memorialized requesting abolition of the state fief;", idiomatic: "The relevant offices memorialized requesting abolition of the state fief;" },
  { zh: "有詔：「長子安嗣爵為樂昌侯。", literal: "there was an edict: \"The eldest son An shall succeed to the title as Marquis of Lechang.", idiomatic: "an edict said, \"The eldest son An shall succeed to the title as Marquis of Lechang." },
  { zh: "」----5　上之為太子也，受《論語》於蓮勺張禹，及即位，賜爵關內侯，拜為諸吏、光祿大夫，秩中二千石，給事中，領尚書事。", literal: "\" ----5 When the emperor had been heir apparent, he received the Analects from Zhang Yu of Lianshu; when he took the throne, Yu was granted the rank of Marquis within the Passes, appointed Gentleman-of-the-Palace and Household Grandee at rank of two thousand bushels, Attendant Within, and put in charge of Masters of Writing affairs.", idiomatic: "\" ----5 When the emperor had been heir apparent, he studied the Analects under Zhang Yu of Lianshu. Upon his accession Yu was made Marquis within the Passes, appointed Gentleman-of-the-Palace and Household Grandee at two-thousand-bushel rank, Attendant Within, and put in charge of the Masters of Writing." },
  { zh: "禹與王鳳並領尚書，內不自安，數病，上書乞骸骨，欲退避鳳；", literal: "Yu and Wang Feng jointly headed the Masters of Writing; inwardly ill at ease, he repeatedly fell ill, submitted memorials begging to retire on old bones, and wished to withdraw and yield to Feng;", idiomatic: "Yu and Wang Feng jointly headed the Masters of Writing. Inwardly uneasy, he repeatedly fell ill, submitted memorials begging to retire, and wished to withdraw and yield to Feng;" },
  { zh: "上不許，撫待愈厚。", literal: "the emperor would not permit it and treated him with ever greater kindness.", idiomatic: "the emperor refused and treated him with ever greater kindness." },
  { zh: "六月，丙戌，以禹為丞相，封安昌侯。", literal: "Sixth month, on bingxu, Yu was made chancellor and enfeoffed as Marquis of Anchang.", idiomatic: "In the sixth month, on bingxu, Yu was made chancellor and enfeoffed as Marquis of Anchang." },
  { zh: "----6　庚戌，楚孝王囂薨。", literal: "----6 On gengxu, King Xiao of Chu Xiao died.", idiomatic: "----6 On gengxu, King Xiao of Chu Xiao died." },
  { zh: "----7　初，武帝通西域，罽賓自以絕遠，漢兵不能至，獨不服，數剽殺漢使。", literal: "----7 Earlier, when Emperor Wu opened the Western Regions, Jibin, thinking itself utterly remote and that Han troops could not arrive, alone did not submit and repeatedly plundered and killed Han envoys.", idiomatic: "----7 Earlier, when Emperor Wu opened the Western Regions, Jibin, thinking itself too remote for Han troops to reach, alone refused to submit and repeatedly plundered and killed Han envoys." },
  { zh: "久之，漢使者文忠與容屈王子陰末赴合謀攻殺其王；", literal: "After a long time, Han envoy Wen Zhong and Yinmofu, prince of Rongqu, joined in a plot to attack and kill its king;", idiomatic: "After a long time Han envoy Wen Zhong and Yinmofu, prince of Rongqu, plotted together to attack and kill its king;" },
  { zh: "立陰末赴為罽賓王。", literal: "Yinmofu was installed as king of Jibin.", idiomatic: "Yinmofu was installed as king of Jibin." },
  { zh: "後軍候趙德使罽賓，與陰末赴相失；", literal: "Later Army Commandant Zhao De was sent to Jibin and fell out with Yinmofu;", idiomatic: "Later Army Commandant Zhao De was sent to Jibin and fell out with Yinmofu;" },
  { zh: "陰末赴鎖琅當德，殺副已下七十餘人，遣使者上書謝。", literal: "Yinmofu shackled De in cangue and stocks, killed the deputy envoy and more than seventy men below him, and sent an envoy to submit a memorial of apology.", idiomatic: "Yinmofu shackled De in cangue and stocks, killed the deputy envoy and more than seventy of his party, and sent an envoy to submit an apology." },
  { zh: "孝元帝以其絕域，不錄，放其使者於縣度，絕而不通。", literal: "Emperor Xiaoyuan, because it was an utterly remote region, did not record the matter and released its envoy at Xiandu, cutting off relations and not communicating.", idiomatic: "Emperor Xiaoyuan, considering it an utterly remote region, took no action and released its envoy at Xiandu, cutting off relations." },
  { zh: "及帝即位，復遣使獻謝罪。", literal: "When the present emperor took the throne, Jibin again sent envoys offering tribute and apologizing for its crime.", idiomatic: "When the present emperor took the throne, Jibin again sent envoys with tribute to apologize for its crimes." },
  { zh: "漢欲遣使者報送其使。", literal: "Han wished to send envoys in return to escort their envoys back.", idiomatic: "Han wished to send envoys in return to escort their envoys home." },
  { zh: "杜欽說王鳳曰：「前罽賓王陰末赴，本漢所立，後卒畔逆。", literal: "Du Qin advised Wang Feng, saying: \"The former king of Jibin Yinmofu was originally installed by Han and afterward in the end rebelled.", idiomatic: "Du Qin advised Wang Feng, saying, \"The former king of Jibin, Yinmofu, was originally installed by Han and later rebelled." },
  { zh: "夫德莫大於有國子民，罪莫大於執殺使者，所以不報恩，不懼誅者，自知絕遠，兵不至也。", literal: "Now no grace is greater than having a state and cherishing the people, and no crime is greater than seizing and killing envoys. The reason he did not repay grace and did not fear execution was that he knew himself utterly remote and that troops could not arrive.", idiomatic: "No grace is greater than holding a state and cherishing one's people, and no crime is greater than seizing and killing envoys. The reason he did not repay Han's favor and did not fear punishment was that he knew himself too remote for troops to reach." },
  { zh: "有求則卑辭，無慾則驕嫚，終不可懷服。", literal: "When he has requests he uses humble words; when he has no desires he is proud and insolent—he can never be won by cherishing.", idiomatic: "When he wants something he speaks humbly; when he wants nothing he is proud and insolent—he can never be won over by kindness." },
  { zh: "凡中國所以為通厚蠻夷，愜快其求者，為壤比而為寇。", literal: "In general, the reason the Central States maintain communication and generous treatment with the barbarian Yi and satisfy their requests is that they are neighbors sharing borders and may become raiders.", idiomatic: "In general the Central States maintain relations and generous treatment with barbarians and satisfy their requests because they are neighbors who may become raiders." },
  { zh: "今縣度之厄，非罽賓所能越也；", literal: "Now the peril of Xiandu is not something Jibin can cross;", idiomatic: "Now the peril of Xiandu is not something Jibin can cross;" },
  { zh: "其鄉慕，不足以安西域；", literal: "its admiration and yearning are insufficient to secure the Western Regions;", idiomatic: "its admiration is insufficient to secure the Western Regions;" },
  { zh: "雖不附，不能危城郭。", literal: "even if it does not attach itself, it cannot endanger cities and walls.", idiomatic: "even if it does not submit, it cannot endanger our cities." },
  { zh: "前親逆節，惡暴西域，故絕而不通；", literal: "Earlier it personally violated righteousness, was violent and cruel in the Western Regions, and therefore relations were cut and there was no communication;", idiomatic: "Earlier it openly rebelled and terrorized the Western Regions, so relations were cut off;" },
  { zh: "今悔過來，而無親屬、貴人，奉獻者皆行賈賤人，欲通貨市買，以獻為名，故煩使者送至縣度，恐失實見欺。", literal: "now it repents and comes, yet there are no kin or nobles; those who bring tribute are all traveling merchants and base men who wish to open trade and market buying, using tribute as a name—therefore troubling envoys to escort them to Xiandu is feared to miss the truth and be deceived.", idiomatic: "now it repents and comes, yet sends no kin or nobles; those who bring tribute are all traveling merchants and common traders who wish to open trade under the name of tribute. Troubling envoys to escort them to Xiandu risks missing the truth and being deceived." },
  { zh: "凡遣使送客者，欲為防護寇害也。", literal: "In general, sending envoys to escort guests is meant to protect against raider harm.", idiomatic: "In general, sending envoys to escort guests is meant to protect them from raiders." },
  { zh: "起皮山，南更不屬漢之國四、五，斥候士百餘人，五分夜擊刁斗自守，尚時為所侵盜。", literal: "From Pishan southward are four or five states no longer belonging to Han; more than a hundred scouts, dividing the night into five watches and striking clappers to guard themselves, are still from time to time raided and robbed.", idiomatic: "From Pishan southward lie four or five states no longer under Han control. More than a hundred scouts, dividing the night into watches and striking clappers to guard themselves, are still from time to time raided." },
  { zh: "驢畜負糧，須諸國稟食，得以自贍。", literal: "Donkeys and livestock carry grain; they must rely on the various states for issued grain to support themselves.", idiomatic: "Donkeys and pack animals carry grain; they must rely on the various states for provisions to support themselves." },
  { zh: "國或貧小不能食，或桀黠不肯給，擁強漢之節，餒山谷之間，乞丐無所得，離一、二旬，則人畜棄捐曠野而不反。", literal: "Some states are poor and small and cannot feed them; some are fierce and cunning and refuse to supply them. Clutching Han's strong credentials, they starve between mountains and valleys, beg and obtain nothing; after one or two ten-day periods, men and livestock are abandoned in the wilds and do not return.", idiomatic: "Some states are too poor and small to feed them; some are fierce and refuse to supply them. Bearing Han's credentials, they starve in the valleys, beg in vain, and after ten or twenty days men and livestock are abandoned in the wilderness and never return." },
  { zh: "又歷大頭痛、小頭痛之山，赤土、身熱之阪，令人身熱無色，頭痛嘔吐，驢畜盡然。", literal: "They also pass the mountains of Great Headache and Little Headache and the slopes of red earth and feverish body, which make men feverish and colorless, with headache and vomiting—and donkeys and livestock are entirely the same.", idiomatic: "They also pass the mountains of Great Headache and Little Headache and the slopes of red earth and feverish body, which make men feverish, pale, and sick with headache and vomiting—and pack animals suffer the same." },
  { zh: "又有三池盤、石阪道，狹者尺六七寸，長者徑三十里，臨崢嶸不測之深，行者騎步相持，繩索相引，二千餘里，乃到縣度。", literal: "There are also the paths of Three Pools and Rocky Slopes; where narrow they are only a foot or six or seven inches, where long they run thirty li straight, overlooking sheer and unfathomable depths. Travelers on horse and foot support one another, ropes draw one another along—more than two thousand li before reaching Xiandu.", idiomatic: "There are also the paths of Three Pools and Rocky Slopes—narrow places only a foot or six or seven inches wide, long stretches running thirty li, overlooking sheer unfathomable depths. Travelers on horse and on foot support one another and are roped together for more than two thousand li before reaching Xiandu." },
  { zh: "畜墜，未半坑谷盡靡碎；", literal: "When livestock fall, before halfway the ravines and valleys are entirely crushed to pieces;", idiomatic: "When livestock fall, before halfway the ravines are littered with shattered animals;" },
  { zh: "人墮，勢不得相收視；", literal: "when men fall, the situation does not allow mutual rescue;", idiomatic: "when men fall, rescue is impossible;" },
  { zh: "險阻危害，不可勝言。", literal: "the dangers of precipices and obstacles cannot be fully told.", idiomatic: "the perils cannot be fully described." },
  { zh: "聖王分九州，制五服，務盛內，不求外；", literal: "Sage kings divided the Nine Provinces and regulated the Five Domains, striving to enrich the interior and not seeking the exterior;", idiomatic: "Sage kings divided the Nine Provinces and regulated the Five Domains, striving to enrich the interior and not seeking the exterior;" },
  { zh: "今遣使者承至尊之命，送蠻夷之賈，勞吏士之眾，涉危難之路，罷敝所恃以事無用，非久長計也。", literal: "now to send envoys bearing the Most Exalted's command, escorting barbarian merchants, toiling officials and soldiers in multitudes, crossing roads of peril and hardship, wearing out what is relied upon for what is useless—this is not a long-term plan.", idiomatic: "to send envoys bearing the Son of Heaven's command to escort barbarian merchants, exhausting officials and soldiers on perilous roads and wearing out our resources for what is useless is not a long-term policy." },
  { zh: "使者業已受節，可至皮山而還。", literal: "The envoys have already received their credentials; they may go as far as Pishan and return.", idiomatic: "The envoys have already received their credentials; they may go as far as Pishan and return." },
  { zh: "」於是鳳白從欽言。", literal: "\" Thereupon Feng reported and followed Qin's advice.", idiomatic: "\" Thereupon Feng reported to the throne and followed Qin's advice." },
  { zh: "罽賓實利賞賜賈市，其使數年而壹至云。", literal: "Jibin in truth valued rewards, gifts, and trade; its envoys came only once every several years, it is said.", idiomatic: "Jibin in truth valued rewards and trade; its envoys came only once every several years, it is said." },
  { zh: "1　春，二月，丁未晦，日有食之。", literal: "1 In spring, the second month, on the last day of the cycle dingwei, there was a solar eclipse.", idiomatic: "1 In spring, the second month, on the last day of dingwei, there was a solar eclipse." },
  { zh: "----2　三月，赦天下徒。", literal: "----2 Third month, there was an amnesty for convict laborers throughout the realm.", idiomatic: "----2 In the third month there was an amnesty for convict laborers throughout the realm." },
  { zh: "----3　冬，京兆尹泰山王章下獄，死。", literal: "----3 In winter, Metropolitan Governor Wang Zhang of Taishan was imprisoned and died.", idiomatic: "----3 In winter, Metropolitan Governor Wang Zhang of Taishan was imprisoned and died." },
  { zh: "時大將軍鳳用事，上謙讓無所顓。", literal: "At the time Grand General Feng held power; the emperor was deferential and had nowhere to focus authority.", idiomatic: "At the time Grand General Feng held power; the emperor was deferential and concentrated no authority in himself." },
  { zh: "左右嘗薦光祿大夫劉向少子歆通達有異材，上召見歆，誦讀詩賦，甚悅之，欲以為中常侍；", literal: "Those around him once recommended Liu Xiang the Household Grandee's younger son Xin as penetrating and possessed of unusual talent; the emperor summoned and saw Xin, who recited poetry and rhapsodies; he was greatly pleased and wished to make him Palace Regular Attendant;", idiomatic: "Those around him once recommended Liu Xiang's younger son Xin as talented and penetrating. The emperor summoned Xin, who recited poetry and rhapsodies. The emperor was greatly pleased and wished to make him Palace Regular Attendant;" },
  { zh: "召取衣冠，臨當拜，左右皆曰：「未曉大將軍。", literal: "He summoned Xin to receive cap and robes; just as he was about to be appointed, those around him all said: \"The Grand General has not been informed.", idiomatic: "He summoned Xin to receive his appointment regalia; just as the appointment was to be made, those around him said, \"The Grand General has not been informed." },
  { zh: "」上曰：「此小事，何須關大將軍！", literal: "\" The emperor said: \"This is a small matter—why must it concern the Grand General!", idiomatic: "\" The emperor said, \"This is a small matter—why must it concern the Grand General!" },
  { zh: "」左右叩頭爭之，上於是語鳳，鳳以為不可，乃止。", literal: "\" Those around him knocked their heads and pressed the point; the emperor thereupon told Feng, and Feng held it could not be done, so it was stopped.", idiomatic: "\" Those around him kowtowed and pressed the point. The emperor then told Feng, who held it could not be done, and the appointment was dropped." },
  { zh: "王氏子弟皆卿、大夫、侍中、諸曹，分據勢官，滿朝廷。", literal: "Wang clan sons and younger brothers were all ministers, grandees, palace attendants, and various bureau posts, occupying powerful offices and filling the court.", idiomatic: "Wang clan sons and younger brothers held posts as ministers, grandees, palace attendants, and bureau offices, occupying powerful positions throughout the court." },
  { zh: "杜欽見鳳專政泰重，戒之曰：「願將軍由周公之謙懼，損穰侯之威，放武安之欲，毋使范雎之徒得間其說。", literal: "Du Qin, seeing Feng's monopoly of government excessively heavy, admonished him, saying: \"I wish the general would follow the Duke of Zhou's humility and fear, reduce Marquis Rang's awe, release Marquis of Wu'an's desires, and not let men like Fan Ju find openings for their persuasions.", idiomatic: "Du Qin, seeing Feng's monopoly of power as excessive, admonished him, saying, \"I wish the general would follow the Duke of Zhou's humility and caution, reduce Marquis Rang's dominance, restrain Marquis of Wu'an's ambitions, and not let men like Fan Ju find an opening for their persuasions." },
  { zh: "」鳳不聽。", literal: "\" Feng would not listen.", idiomatic: "\" Feng would not listen." },
  { zh: "時上無繼嗣，體常不平。", literal: "At the time the emperor had no heir; his health was often unwell.", idiomatic: "At the time the emperor had no heir and was often unwell." },
  { zh: "定陶共王來朝，太后與上承先帝意，遇共王甚厚，賞賜十倍於它王，不以往事為纖介；", literal: "King Gong of Dingtao came to court; the empress dowager and the emperor, following the late emperor's intent, treated King Gong very generously, with rewards ten times those of other kings, not taking past matters as the slightest grievance;", idiomatic: "King Gong of Dingtao came to court. The empress dowager and the emperor, following the late emperor's intent, treated him very generously, with rewards ten times those of other kings, making nothing of past grievances;" },
  { zh: "留之京師，不遣歸國。", literal: "they kept him in the capital and did not send him back to his state.", idiomatic: "they kept him in the capital and did not send him back to his state." },
  { zh: "上謂共王：「我未有子，人命不諱。", literal: "The emperor said to King Gong: \"I have no son; human life admits no taboo.", idiomatic: "The emperor said to King Gong, \"I have no son; one must not shrink from speaking of death." },
  { zh: "一朝有它，且不復相見，爾長留侍我矣！", literal: "If in a single morning something else should happen, we shall not meet again—you had better stay long and attend me!", idiomatic: "If something should happen suddenly, we may not meet again—you should stay and attend me!" },
  { zh: "」其後天子疾益有瘳，共王因留國邸，旦夕侍上。", literal: "\" Afterward the Son of Heaven's illness gradually improved somewhat; King Gong therefore remained at the state residence in the capital, attending the emperor morning and evening.", idiomatic: "\" Afterward the emperor's illness gradually improved. King Gong therefore remained at his residence in the capital and attended the emperor morning and evening." },
  { zh: "上甚親重之。", literal: "The emperor was very close to and valued him.", idiomatic: "The emperor grew very fond of him." },
  { zh: "大將軍鳳心不便共王在京師，會日食，鳳因言：「日食，陰盛之象。", literal: "Grand General Feng inwardly disliked King Gong's presence in the capital; when a solar eclipse occurred, Feng thereupon said: \"A solar eclipse is the sign of yin in excess.", idiomatic: "Grand General Feng inwardly disliked King Gong's presence in the capital. When a solar eclipse occurred, Feng said, \"A solar eclipse is a sign of excess yin." },
  { zh: "定陶王雖親，於禮當奉籓在國；", literal: "The King of Dingtao, though close kin, by ritual ought to hold his fief and remain in his state;", idiomatic: "The King of Dingtao, though a close relative, by ritual ought to remain in his fief;" },
  { zh: "今留侍京師，詭正非常，故天見戒，宜遣王之國。", literal: "now to remain attending in the capital is perverse and irregular, and therefore Heaven has shown a warning—the king ought to be sent to his state.", idiomatic: "to remain attending in the capital is irregular, and therefore Heaven has shown a warning. The king ought to be sent back to his state." },
  { zh: "」上不得已於鳳而許之。", literal: "\" The emperor, having no alternative because of Feng, agreed.", idiomatic: "\" The emperor, unable to refuse Feng, agreed." },
  { zh: "共王辭去，上與相對涕泣而決。", literal: "King Gong took his leave; the emperor faced him, weeping and taking farewell in tears.", idiomatic: "King Gong took his leave; the emperor faced him, and they wept as they parted." },
  { zh: "王章素剛直敢言，雖為鳳所舉，非鳳專權，不親附鳳，乃奏封事，言：「日食之咎，皆鳳專權蔽主之過。", literal: "Wang Zhang had always been upright and bold in speech; though raised up by Feng, he did not side with Feng's monopoly of power or attach himself closely to Feng. He thereupon submitted a sealed memorial, saying: \"The blame for the solar eclipse lies entirely in Feng's monopolizing power and obscuring the ruler.", idiomatic: "Wang Zhang had always been upright and outspoken. Though promoted by Feng, he did not side with Feng's monopoly of power or attach himself to him. He submitted a sealed memorial, saying, \"The blame for the solar eclipse lies entirely in Feng's monopolizing power and keeping the ruler in the dark." },
  { zh: "」上召見章，延問以事。", literal: "\" The emperor summoned Zhang and questioned him at length on the matter.", idiomatic: "\" The emperor summoned Zhang and questioned him at length." },
  { zh: "章對曰：「天道聰明，佑善而災惡，以瑞異為符效。", literal: "Zhang replied: \"The Way of Heaven is discerning; it aids the good and punishes the evil, taking auspicious and strange events as tokens of effect.", idiomatic: "Zhang replied, \"Heaven is discerning; it aids the good and punishes the evil, using omens and anomalies as signs of its judgment." },
  { zh: "今陛下以未有繼嗣，引近定陶王，所以承宗廟，重社稷，上順天心，下安百姓，此正議善事，當有祥瑞，何故致災異！", literal: "Now Your Majesty, because you have no heir, has drawn near the King of Dingtao to continue the ancestral temples and weight the altars of soil and grain—above it accords with Heaven's heart, below it settles the hundred clans. This is upright counsel and a good deed; there ought to be auspicious omens—why bring on strange calamities!", idiomatic: "Your Majesty, having no heir, has drawn near the King of Dingtao to continue the ancestral temples and secure the state—above it accords with Heaven's will, below it settles the people. This is upright and good policy; there ought to be auspicious omens. Why should it bring calamities!" },
  { zh: "災異之發，為大臣顓政者也。", literal: "The arising of strange calamities is on account of great ministers monopolizing government.", idiomatic: "Strange calamities arise when great ministers monopolize government." },
  { zh: "今聞大將軍猥歸日食之咎於定陶王，建遣之國，苟欲使天子孤立於上，顓擅朝事以便其私，非忠臣也。", literal: "Now I hear the Grand General-in-Chief basely ascribed the solar eclipse's blame to the King of Dingtao and urged sending him to his state, merely wishing to leave the Son of Heaven isolated above and monopolize court affairs for his private ends—not a loyal minister.", idiomatic: "I hear the Grand General-in-Chief basely blamed the solar eclipse on the King of Dingtao and urged sending him home, merely to leave the emperor isolated above and monopolize court affairs for his own ends. That is not the conduct of a loyal minister." },
  { zh: "且日食，陰侵陽，臣顓君之咎。", literal: "Moreover, a solar eclipse means yin invading yang—the fault of a minister monopolizing his lord.", idiomatic: "Moreover, a solar eclipse means yin invading yang—the fault of a minister who monopolizes his lord." },
  { zh: "今政事大小皆自鳳出，天子曾不壹舉手，鳳不內省責，反歸咎善人，推遠定陶王。", literal: "Now affairs great and small all come from Feng; the Son of Heaven has not once raised a hand. Feng does not look inward and blame himself but instead ascribes blame to a good man and pushes the King of Dingtao away.", idiomatic: "Now affairs great and small all come from Feng, and the emperor has not once raised a hand. Feng does not examine himself but instead blames a good man and pushes the King of Dingtao away." },
  { zh: "且鳳誣罔不忠，非一事也。", literal: "Moreover, Feng's deception and disloyalty are not limited to one matter.", idiomatic: "Moreover, Feng's deception and disloyalty are not limited to one matter." },
  { zh: "前丞相樂昌侯商，本以先帝外屬，內行篤，有威重，位歷將相，國家柱石臣也，其人守正，不肯屈節隨鳳委曲；", literal: "Formerly Chancellor Marquis of Lechang Shang, by origin a maternal relative of the late emperor, inwardly steadfast in conduct, possessed authority and weight, had held posts through general and chancellor, and was a pillar minister of the state. The man kept to rectitude and would not bend his integrity to follow Feng's twists;", idiomatic: "Former Chancellor Marquis of Lechang Shang was a maternal relative of the late emperor, inwardly steadfast, possessed authority and weight, had risen through general and chancellor, and was a pillar of the state. He kept to rectitude and would not bend to Feng's will;" },
  { zh: "卒用閨門之事為鳳所罷，身以憂死，眾庶愍之。", literal: "in the end on account of inner-chamber matters he was dismissed by Feng, died himself from grief, and the multitude pitied him.", idiomatic: "in the end Feng used inner-chamber matters to have him dismissed; he died of grief, and the people pitied him." },
  { zh: "又鳳知其小婦弟張美人已嘗適人，於禮不宜配御至尊，托以為宜子，內之後宮，苟以私其妻弟；", literal: "Again, Feng knew that his wife's younger brother's wife, Lady Zhang, had already been married to another man and by ritual ought not be matched to attend the Most Exalted. He pretended she was fit to bear sons and brought her into the inner palace, merely to favor his wife's brother privately;", idiomatic: "Again, Feng knew that his wife's younger brother's wife, Lady Zhang, had already been married and by ritual ought not enter the imperial harem. He pretended she was fit to bear sons and brought her into the palace merely to favor his wife's brother;" },
  { zh: "聞張美人未嘗任身就館也。", literal: "I hear Lady Zhang has never once conceived and entered the lodging.", idiomatic: "I hear Lady Zhang has never once conceived." },
  { zh: "且羌、胡尚殺首子以蕩腸正世，況於天子，而近已出之女也！", literal: "Moreover, even the Qiang and Hu still kill the first son to cleanse the womb and rectify the age—how much more for the Son of Heaven to take near a woman already given in marriage!", idiomatic: "Even the Qiang and Hu kill the first son to cleanse the womb and rectify the lineage—how much less should the Son of Heaven take a woman already given in marriage!" },
  { zh: "此三者皆大事，陛下所自見，足以知其餘及它所不見者。", literal: "These three are all great matters Your Majesty has yourself witnessed, sufficient to know the rest and what you have not witnessed.", idiomatic: "These three are all grave matters Your Majesty has witnessed yourself, enough to judge the rest and what you have not seen." },
  { zh: "鳳不可令久典事，宜退使就第，選忠賢以代之！", literal: "Feng must not be allowed to hold affairs long; he ought to be made to withdraw to his residence and loyal worthies chosen to replace him!", idiomatic: "Feng must not be allowed to hold power long. He ought to withdraw to his residence and loyal worthies be chosen to replace him!" },
  { zh: "」自鳳之白罷商，後遣定陶王也，上不能平；", literal: "\" From the time Feng had urged dismissing Shang and afterward sent the King of Dingtao away, the emperor could not be at peace;", idiomatic: "\" From the time Feng had Shang dismissed and afterward sent the King of Dingtao away, the emperor had been ill at ease;" },
  { zh: "及聞章言，天子感寤，納之，謂章曰：「微京兆尹直言，吾不聞社稷計。", literal: "when he heard Zhang's words, the Son of Heaven was moved and awakened, accepted them, and said to Zhang: \"But for the Metropolitan Governor's straight speech, I would not have heard counsel for the altars of soil and grain.", idiomatic: "when he heard Zhang's words, the emperor was moved and accepted them. He said to Zhang, \"But for the Metropolitan Governor's frank speech, I would never have heard counsel for the state." },
  { zh: "且唯賢知賢，君試為朕求可以自輔者。", literal: "Moreover, only the worthy know the worthy. You try to seek for Us someone who can assist Us.", idiomatic: "Moreover, only the worthy know the worthy. Try to find someone who can assist me." },
  { zh: "」於是章奏封事，薦信都王舅琅邪太守馮野王，忠信質直，知謀有餘。", literal: "\" Thereupon Zhang submitted a sealed memorial recommending the King of Xindu's maternal uncle, Administrator of Langye Feng Yewang—loyal, trustworthy, plain and upright, with knowledge and stratagem to spare.", idiomatic: "\" Thereupon Zhang submitted a sealed memorial recommending the King of Xindu's maternal uncle, Administrator of Langye Feng Yewang, as loyal, trustworthy, plain and upright, with knowledge and stratagem to spare." },
  { zh: "以王舅出，以賢復入，明聖主樂進賢也。", literal: "Because he was a king's maternal uncle he went out; because he was worthy he should come back in—this shows a sage ruler delights in advancing the worthy.", idiomatic: "Sent out because he was a king's maternal uncle, he should be brought back because he is worthy—this shows a sage ruler delights in advancing the worthy." },
  { zh: "上自為太子時，數聞野王先帝名卿，聲譽出鳳遠甚，方倚欲以代鳳。", literal: "The emperor, from the time he had been heir apparent, had often heard that Yewang was a famed minister of the late emperor and that his reputation far exceeded Feng's; he was just then relying on him and wished to use him to replace Feng.", idiomatic: "From his days as heir apparent the emperor had often heard that Yewang was a famed minister of the late emperor and that his reputation far exceeded Feng's. He was just then inclined to use him to replace Feng." },
  { zh: "章每召見，上輒辟左右。", literal: "Whenever Zhang was summoned, the emperor would dismiss those at his side.", idiomatic: "Whenever Zhang was summoned, the emperor dismissed those at his side." },
  { zh: "時太后從弟子侍中音獨側聽，具知章言，以語鳳。", literal: "At the time the empress dowager's maternal nephew Palace Attendant Yin alone listened from the side, knew Zhang's words in full, and told Feng.", idiomatic: "At the time the empress dowager's maternal nephew, Palace Attendant Yin, listened from the side, learned Zhang's words in full, and told Feng." },
  { zh: "鳳聞之，甚憂懼。", literal: "When Feng heard it, he was greatly worried and afraid.", idiomatic: "When Feng heard it, he was greatly alarmed." },
  { zh: "杜欽令鳳稱病出就第，上疏乞骸骨，其辭指甚哀。", literal: "Du Qin had Feng claim illness and go out to his residence, submit a memorial begging to retire on old bones—the wording and purport very mournful.", idiomatic: "Du Qin had Feng claim illness and withdraw to his residence, submit a memorial begging to retire—the wording very mournful." },
  { zh: "太后聞之，為垂涕，不御食。", literal: "When the empress dowager heard it, she wept for him and would not take her meal.", idiomatic: "When the empress dowager heard it, she wept for him and refused her meal." },
  { zh: "上少而親倚鳳，弗忍廢，乃優詔報鳳，強起之；", literal: "The emperor from youth had been close to and relied on Feng and could not bear to dismiss him; he therefore replied to Feng with a gracious edict and forced him to rise again;", idiomatic: "The emperor had been close to Feng since youth and could not bear to dismiss him. He replied with a gracious edict and forced him to return;" },
  { zh: "於是鳳起視事。", literal: "thereupon Feng rose and attended to affairs.", idiomatic: "thereupon Feng returned and resumed his duties." },
  { zh: "上使尚書劾奏章：「知野王前以王舅出補吏，而私薦之，欲令在朝，阿附諸侯；", literal: "The emperor had the Masters of Writing impeach and memorialize against Zhang: \"Knowing that Yewang had earlier been sent out to fill an outside post because he was a king's maternal uncle, yet privately recommending him, wishing to have him remain at court and fawn upon the feudal lords;", idiomatic: "The emperor had the Masters of Writing impeach Zhang: \"Knowing that Yewang had earlier been sent to a provincial post because he was a king's maternal uncle, yet privately recommending him to remain at court and curry favor with the feudal lords;" },
  { zh: "又知張美人體御至尊，而妄稱引羌胡殺子蕩腸，非所宜言。", literal: "and also knowing that Lady Zhang attended the Most Exalted's person, yet recklessly cited the Qiang and Hu killing sons to cleanse the womb—speech not fitting to be uttered.", idiomatic: "and also knowing that Lady Zhang attended the emperor, yet recklessly cited the Qiang and Hu killing sons to cleanse the womb—speech unfit to be uttered." },
  { zh: "」下章吏。", literal: "\" Zhang was sent down to the officials.", idiomatic: "\" Zhang was handed over to the officials." },
  { zh: "廷尉致其大逆罪，以為「比上夷狄，欲絕繼嗣之端，背畔天子，私為定陶王。", literal: "The Commandant of Justice charged him with the crime of great treason, holding that he \"compared his lord to barbarians, wished to cut off the succession, turned his back on the Son of Heaven, and privately acted for the King of Dingtao.", idiomatic: "The Commandant of Justice charged him with great treason, holding that he \"compared his lord to barbarians, sought to cut off the succession, turned against the emperor, and privately acted for the King of Dingtao." },
  { zh: "」章竟死獄中，妻子徙合浦。", literal: "\" Zhang in the end died in prison; his wife and children were banished to Hepu.", idiomatic: "\" Zhang died in prison; his wife and children were banished to Hepu." },
  { zh: "自是公卿見鳳，側目而視。", literal: "From this time, when dukes and ministers saw Feng, they looked askance.", idiomatic: "From this time, when dukes and ministers saw Feng, they looked askance." },
  { zh: "馮野王懼不自安，遂病；", literal: "Feng Yewang, afraid and ill at ease, then fell ill;", idiomatic: "Feng Yewang, afraid and ill at ease, fell ill;" },
  { zh: "滿三月，賜告，與妻子歸杜陵就醫藥。", literal: "when three months were full he was granted leave and, with wife and children, returned to Duling to seek medicine.", idiomatic: "after three months he was granted leave and, with wife and children, returned to Duling to seek treatment." },
  { zh: "大將軍鳳風御史中丞劾奏「野王賜告養病而私自便，持虎符出界歸家，奉詔不敬。", literal: "Grand General-in-Chief Feng had the Vice Censor-in-Chief impeach and memorialize that \"Yewang, granted leave to nurse illness, privately took his ease, carried the tiger tally across the border to return home, and was disrespectful in obeying the edict.", idiomatic: "Grand General-in-Chief Feng had the Vice Censor-in-Chief impeach Yewang for \"having been granted leave to nurse illness, yet taking his ease privately, carrying the tiger tally across the border to return home, and showing disrespect in obeying the edict." },
  { zh: "」杜欽奏記於鳳曰：「二千石病，賜告得歸，有故事；", literal: "\" Du Qin submitted a note to Feng, saying: \"When a two-thousand-bushel official is ill, grant of leave to return home has precedent;", idiomatic: "\" Du Qin submitted a note to Feng, saying, \"When a two-thousand-bushel official is ill, leave to return home has precedent;" },
  { zh: "不得去郡，亡著令。", literal: "not being allowed to leave the commandery—there is no written statute.", idiomatic: "a prohibition on leaving the commandery has no written statute." },
  { zh: "《傳》曰：『賞疑從予，』所以廣恩勸功也；", literal: "The Commentary says: 'When reward is doubtful, follow granting it'—thereby to extend grace and encourage merit;", idiomatic: "The Commentary says, 'When reward is doubtful, grant it'—thereby to extend grace and encourage merit;" },
  { zh: "『罰疑從去，』所以慎刑，闕難知也。", literal: "'When punishment is doubtful, follow removing it'—thereby to be cautious in punishment, for what is lacking is hard to know.", idiomatic: "'When punishment is doubtful, waive it'—thereby to be cautious in punishment, for what is unclear is hard to know." },
  { zh: "今釋令與故事而假不敬之法，甚違『闕疑從去』之意。", literal: "Now to set aside statute and precedent and borrow the law of disrespect is greatly at odds with the meaning of 'when doubtful, remove punishment.'", idiomatic: "To set aside statute and precedent and borrow the law of disrespect is greatly at odds with 'when doubtful, waive punishment.'" },
  { zh: "即以二千石守千里之地，任兵馬之重，不宜去郡，將以制刑為後法者，則野王之罪在未制令前也。", literal: "Even if, because a two-thousand-bushel official guards a territory of a thousand li and bears the weight of troops and horses, he ought not leave the commandery, and one would make punishment a later standard—then Yewang's offense was before any such statute was made.", idiomatic: "Even if a two-thousand-bushel official guarding a thousand-li territory and bearing command of troops ought not leave his commandery, and one wished to make this a standard for future punishment—Yewang's offense came before any such statute existed." },
  { zh: "刑賞大信，不可不慎。", literal: "Punishment and reward are great trust and must not be treated lightly.", idiomatic: "Punishment and reward are matters of great public trust and must not be treated lightly." },
  { zh: "」鳳不聽，竟免野王官。", literal: "\" Feng would not listen and in the end dismissed Yewang from office.", idiomatic: "\" Feng would not listen and in the end dismissed Yewang from office." },
  { zh: "時眾庶多冤王章譏朝廷者，欽欲救其過，復說鳳曰：「京兆尹章，所坐事密，自京師不曉，況於遠方！", literal: "At the time the multitude widely considered Wang Zhang wronged and mocked the court. Qin wished to remedy the fault and again advised Feng, saying: \"Metropolitan Governor Zhang's offense was secret—even the capital did not understand it, how much less the distant regions!", idiomatic: "At the time many considered Wang Zhang wronged and mocked the court. Qin wished to remedy the damage and again advised Feng, saying, \"Metropolitan Governor Zhang's offense was secret—even the capital did not understand it, how much less the distant regions!" },
  { zh: "恐天下不知章實有罪，而以為坐言事。", literal: "I fear the realm will not know Zhang was truly guilty and will think he was punished for speaking.", idiomatic: "I fear the realm will not know Zhang was truly guilty and will think he was punished for speaking out." },
  { zh: "如是，塞爭引之原，損寬明之德。", literal: "If so, the source of striving and remonstrance is blocked and the virtue of generosity and clarity is harmed.", idiomatic: "If so, the source of remonstrance is blocked and the virtue of generosity and clarity is harmed." },
  { zh: "欽愚以為宜因章事舉直言極諫，並見郎從官，展盡其意，加於往前，以明示四方，使天下咸知主上聖明，不以言罪下也。", literal: "Qin foolishly considers it fitting, on account of Zhang's affair, to hold an assembly for straight speech and extreme remonstrance, summon together gentleman-attendants and attendants, unfold their intent to the full, and increase it beyond before, thereby clearly to show the four quarters and make the realm all know the lord above is sage and bright and does not punish subordinates for words.", idiomatic: "Qin humbly considers it fitting, on account of Zhang's affair, to hold an assembly for frank remonstrance, summon gentleman-attendants and attendants, let them speak their minds fully, and go beyond previous practice, thereby to show the four quarters clearly that the ruler is sage and does not punish subordinates for their words." },
  { zh: "若此，則流言消釋，疑惑著明。", literal: "If so, wandering talk will dissolve and doubt be made clear.", idiomatic: "If so, rumor will dissolve and doubt be made clear." },
  { zh: "」鳳白行其策焉。", literal: "\" Feng reported and carried out this plan.", idiomatic: "\" Feng reported and carried out this plan." },
  { zh: "----4　是歲，陳留太守薛宣為左馮翊。", literal: "----4 That year, Administrator of Chenliu Xue Xuan became Left Governor of Metropolis.", idiomatic: "----4 That year, Administrator of Chenliu Xue Xuan became Left Governor of Metropolis." },
  { zh: "宣為郡，所至有聲跡。", literal: "Wherever Xuan served as commandery administrator, he left a reputation and record.", idiomatic: "Wherever Xuan served as commandery administrator, he left a strong reputation." },
  { zh: "宣子惠為彭城令，宣嘗過其縣，心知惠不能，不問以吏事。", literal: "Xuan's son Hui was Magistrate of Pengcheng. Xuan once passed through his county, knew in his heart that Hui was incapable, and did not question him about official business.", idiomatic: "Xuan's son Hui was Magistrate of Pengcheng. Xuan once passed through his county, knew Hui was incapable, and did not question him about official business." },
  { zh: "或問宣：「何不教戒惠以吏職？", literal: "Someone asked Xuan: \"Why not instruct and admonish Hui in the duties of an official?", idiomatic: "Someone asked Xuan, \"Why not instruct Hui in the duties of an official?" },
  { zh: "」宣笑曰：「吏道以法令為師，可問而知；", literal: "\" Xuan smiled and said: \"The way of officials takes statutes and ordinances as teacher—it can be learned by inquiry;", idiomatic: "\" Xuan smiled and said, \"The way of officials takes statutes and ordinances as its teacher; that can be learned by inquiry." },
  { zh: "及能與不能，自有資材，何可學也！", literal: "as for being able or not, each has his own native talent—how can that be studied!", idiomatic: "as for ability or lack of it, each has his own native talent—how can that be taught!" },
  { zh: "」眾人傳稱，以宣言為然。", literal: "\" The crowd passed the story around and held Xuan's words correct.", idiomatic: "\" The crowd passed the story around and held Xuan's words to be right." },
  { zh: "1　春，三月，大赦天下。", literal: "1 In spring, the third month, there was a general amnesty throughout the realm.", idiomatic: "1 In spring, the third month, the empire was pardoned." },
  { zh: "----2　御史大夫張忠卒。", literal: "----2 Censor-in-Chief Zhang Zhong died.", idiomatic: "----2 Censor-in-Chief Zhang Zhong died." },
  { zh: "夏，四月，丁卯，以侍中、太僕王音為御史大夫。", literal: "Summer, fourth month, on dingmao, Palace Attendant and Grand Steward Wang Yin was made Censor-in-Chief.", idiomatic: "In summer, the fourth month, on dingmao, Palace Attendant and Grand Steward Wang Yin was made Censor-in-Chief." },
  { zh: "於是王氏愈盛，郡國守相、刺史皆出其門下。", literal: "Thereupon the Wang clan grew ever more powerful; commandery and state administrators, commandants, and regional inspectors all came from their following.", idiomatic: "Thereupon the Wang clan grew ever more powerful; commandery and state administrators, commandants, and regional inspectors all came from their following." },
  { zh: "五侯群弟爭為奢侈，賂遺珍寶，四面而至，皆通敏人事，好士養賢，傾財施予以相高尚；", literal: "The Five Marquises' younger brothers vied in luxury; bribes and gifts of precious objects arrived from all four sides. All were adept in human affairs, loved scholars and nurtured the worthy, poured out wealth in gifts to match one another in loftiness;", idiomatic: "The Five Marquises' younger brothers vied in luxury; bribes and precious gifts arrived from all sides. All were adept in affairs, loved scholars and nurtured the worthy, and poured out wealth to outdo one another in prestige;" },
  { zh: "賓客滿門，競為之聲譽。", literal: "guests filled their gates, and they competed to build reputation for one another.", idiomatic: "their gates were filled with guests, and they competed to build one another's reputations." },
  { zh: "劉向謂陳湯曰：「今災異如此，而外家日盛，其漸必危劉氏。", literal: "Liu Xiang said to Chen Tang: \"Now strange calamities are like this, while the consort kin grow daily in power—their gradual advance is sure to endanger the Liu clan.", idiomatic: "Liu Xiang said to Chen Tang, \"Strange calamities are multiplying, while the consort kin grow daily in power—their gradual advance is sure to endanger the Liu clan." },
  { zh: "吾幸得以同姓末屬，累世蒙漢厚恩，身為宗室遺老，歷事三主。", literal: "I am fortunate to be a junior branch of the same surname, to have received Han's thick grace through successive generations, to stand as a surviving elder of the imperial clan, and to have served three rulers.", idiomatic: "I am fortunate to be a junior branch of the imperial house, to have received Han's generous favor through successive generations, to stand as a surviving elder of the clan, and to have served three emperors." },
  { zh: "上以我先帝舊臣，每進見，常加優禮。", literal: "The emperor, because I am an old minister of the late emperor, whenever I am admitted to audience, always adds gracious treatment.", idiomatic: "The emperor, because I am an old minister of the late emperor, always treats me with special courtesy when I am admitted to audience." },
  { zh: "吾而不言，孰當言者！", literal: "If I do not speak, who should speak!", idiomatic: "If I do not speak, who should!" },
  { zh: "」遂上封事極諫曰：「臣聞人君莫不欲安，然而常危；", literal: "\" He thereupon submitted a sealed memorial of extreme remonstrance, saying: \"Your servant has heard that a ruler desires security, yet is often in peril;", idiomatic: "\" He thereupon submitted a sealed memorial of extreme remonstrance, saying, \"I have heard that a ruler desires security, yet is often in peril;" },
  { zh: "莫不欲存，然而常亡；", literal: "desires preservation, yet is often destroyed;", idiomatic: "desires preservation, yet is often destroyed;" },
  { zh: "失御臣之術也。", literal: "this is from losing the art of controlling ministers.", idiomatic: "this comes from losing the art of controlling ministers." },
  { zh: "夫大臣操權柄，持國政，未有不為害者也。", literal: "When great ministers grasp power's handle and hold the state's government, there has never been one who did not become harmful.", idiomatic: "When great ministers grasp power and hold the state's government, they have never failed to do harm." },
  { zh: "故《書》曰：『臣之有作威作福，害於而家，凶於而國。", literal: "Therefore the Documents says: 'When ministers make authority and make blessings, it harms your house and is ominous for your state.", idiomatic: "Therefore the Documents says, 'When ministers make authority and make blessings, it harms your house and is ominous for your state." },
  { zh: "』孔子曰：『祿去公室，政逮大夫，』危亡之兆也。", literal: "' Confucius said: 'When emoluments leave the ducal house and government reaches the grandees'—the omen of peril and destruction.", idiomatic: "' Confucius said, 'When emoluments leave the ducal house and government reaches the grandees'—the omen of peril and destruction." },
  { zh: "今王氏一姓，乘朱輪華轂者二十三人，青、紫、貂、蟬充盈幄內，魚鱗左右。", literal: "Now the Wang surname alone: twenty-three who ride vermilion wheels and ornate hubs; green, purple, marten, and cicada insignia fill the curtains within, packed like fish scales at left and right.", idiomatic: "Now the Wang clan alone numbers twenty-three who ride vermilion wheels and ornate hubs; green, purple, marten, and cicada insignia fill the court like fish scales on either hand." },
  { zh: "大將軍秉事用權，五侯驕奢僭盛，並作威福，擊斷自恣，行污而寄治，身私而托公，依東宮之尊，假甥舅之親，以為威重。", literal: "The Grand General-in-Chief holds affairs and wields power; the Five Marquises are proud, extravagant, and transgressively great. Together they make authority and blessings, strike judgments and indulge themselves, practice filth while lodging governance elsewhere, keep the body private while borrowing the public, rely on the Eastern Palace's eminence, and borrow the closeness of nephew and maternal uncle for weight of awe.", idiomatic: "The Grand General-in-Chief holds affairs and wields power; the Five Marquises are proud, extravagant, and overweening. Together they make show of authority and favor, strike judgments at will, practice corruption while lodging governance elsewhere, pursue private ends in public name, rely on the empress dowager's eminence, and borrow the closeness of nephew and maternal uncle for their power." },
  { zh: "尚書、九卿、州牧、郡守皆出其門，管執樞機，朋黨比周；", literal: "Masters of Writing, Nine Ministers, regional governors, and commandery administrators all come from their gate; they grasp the pivots of power and form factions that band together;", idiomatic: "Masters of Writing, Nine Ministers, regional governors, and commandery administrators all come from their gate; they grasp the pivots of power and form factions;" },
  { zh: "稱譽者登進，忤恨者誅傷；", literal: "those they praise are promoted; those they resent are punished and harmed;", idiomatic: "those they praise are promoted; those they resent are punished;" },
  { zh: "游談者助之說，執政者為之言，排擯宗室，孤弱公族，其有智能者，尤非毀而不進，遠絕宗室之任，不令得給事朝省，恐其與己分權；", literal: "wandering talkers assist their persuasions, those who hold government speak for them, they push aside the imperial clan and isolate and weaken the ducal houses. Those with intelligence they especially slander and do not advance, keeping the imperial clan far from office and not allowing them to serve in the court departments, fearing they would share power with themselves;", idiomatic: "flatterers assist their cause, officeholders speak for them, they push aside the imperial clan and isolate the ducal houses. Those with talent they especially slander and block from advancement, keeping the imperial clan far from office lest they share power;" },
  { zh: "數稱燕王、蓋主以疑上心，避諱呂、霍而弗肯稱。", literal: "they repeatedly cite the King of Yan and the Princess of Gai to make the ruler's heart doubtful, yet avoid naming Lü and Huo and will not speak them.", idiomatic: "they repeatedly cite the King of Yan and the Princess of Gai to sow doubt in the emperor's mind, yet avoid naming Lü and Huo." },
  { zh: "內有管、蔡之萌，外假周公之論，兄弟據重，宗族磐互，歷上古至秦、漢，外戚僭貴未有如王氏者也。", literal: "Within they have the sprout of Guan and Cai; without they borrow the argument of the Duke of Zhou. Brothers hold heavy power; the clan is interlocked like bedrock. From high antiquity through Qin and Han, no consort kin have transgressed in honor like the Wang clan.", idiomatic: "Within they harbor the sprout of Guan and Cai; without they borrow the argument of the Duke of Zhou. Brothers hold heavy power; the clan is interlocked. From antiquity through Qin and Han, no consort kin have grown so presumptuous as the Wang clan." },
  { zh: "物盛必有非常之變先見，為其人微象。", literal: "When things reach fullness, there must first appear an extraordinary change as a slight omen for its person.", idiomatic: "When things reach their peak, an extraordinary change must appear first as a slight omen." },
  { zh: "孝昭帝時，冠石立於泰山，僕柳起於上林，而孝宣帝即位。", literal: "In the time of Emperor Xiaozhao, a cap-stone stood up on Mount Tai and a leaning willow rose in Shanglin, and Emperor Xiaoxuan took the throne.", idiomatic: "In the time of Emperor Xiaozhao, a cap-stone stood up on Mount Tai and a leaning willow rose in Shanglin, and Emperor Xiaoxuan took the throne." },
  { zh: "今王氏先祖墳墓在濟南者，其梓柱生枝葉，扶疏上出屋，根垂地中，雖立石起柳，無以過此之明也。", literal: "Now at the Wang clan's ancestral tombs in Jinan, their catalpa pillars have sprouted branches and leaves, spreading upward and out through the roof, roots hanging into the earth below—even standing stone and rising willow cannot surpass this in clarity.", idiomatic: "Now at the Wang clan's ancestral tombs in Jinan, their catalpa pillars have sprouted branches and leaves, spreading upward through the roof with roots hanging into the earth—even standing stone and rising willow cannot surpass this as an omen." },
  { zh: "事勢不兩大，王氏與劉氏亦且不並立，如下有泰山之安，則上有累卵之危。", literal: "Circumstances do not allow two great powers; the Wang clan and the Liu clan likewise cannot stand together. If below there is Mount Tai's security, then above there is the peril of piled eggs.", idiomatic: "Two great powers cannot coexist; the Wang clan and the Liu clan cannot stand together. If below there is Mount Tai's security, then above there is the peril of eggs piled one atop another." },
  { zh: "陛下為人子孫，守持宗廟，而令國祚移於外親，降為皁隸，縱不為身，奈宗廟何！", literal: "Your Majesty, as a descendant of men, guards and holds the ancestral temples—yet would let the state's fate shift to consort kin and be reduced to common black-clad. Even if not for your own person, what of the ancestral temples!", idiomatic: "Your Majesty, as heir to the throne, guards the ancestral temples—yet would let the state's fate pass to consort kin and reduce the house to commoners. Even if not for yourself, what of the ancestral temples!" },
  { zh: "婦人內夫家而外父母家，此亦非皇太后之福也。", literal: "A woman makes her husband's house inner and her parents' house outer—this is also not a blessing for the empress dowager.", idiomatic: "A woman favors her husband's house over her parents' house—this is no blessing for the empress dowager either." },
  { zh: "孝宣皇帝不與舅平昌侯權，所以全安之也。", literal: "Emperor Xiaoxuan did not give his maternal uncle Marquis of Pingchang power—thereby to preserve and secure him.", idiomatic: "Emperor Xiaoxuan did not give his maternal uncle, Marquis of Pingchang, power—thereby to preserve and secure him." },
  { zh: "夫明者起福於無形，銷患於未然，宜發明詔，吐德音，援近宗室，親而納信，黜遠外戚，毋授以政，皆罷令就弟，以則效先帝之所行，厚安外戚，全其宗族，誠東宮之意，外家之福也。", literal: "The discerning raise blessing from the formless and dissolve harm before it arises. It is fitting to issue a brilliant edict, utter a virtuous tone, draw near the imperial clan and be close and admit trust, dismiss distant consort kin and not grant them government, all making them withdraw to their residences, thereby to model what the late emperor practiced, richly to settle the consort kin and preserve their clan—truly the empress dowager's intent and the consort family's blessing.", idiomatic: "The discerning raise blessing before it takes form and dissolve harm before it arises. Issue a brilliant edict, speak with virtue, draw the imperial clan near and trust them, dismiss distant consort kin and grant them no government, make them all withdraw to their residences, model what the late emperor practiced, richly settle the consort kin and preserve their clan—truly the empress dowager's wish and the consort family's blessing." },
  { zh: "王氏永存，保其爵祿，劉氏長安，不失社稷，所以褒睦外內之姓，子子孫孫無疆之計也。", literal: "The Wang clan would endure forever, preserving their titles and emoluments; the Liu clan would long be secure, not losing the altars of soil and grain—thereby to praise and harmonize surnames within and without, a plan without boundary for sons and sons' sons.", idiomatic: "The Wang clan would endure, preserving their titles and emoluments; the Liu clan would long be secure, not losing the state—thereby to harmonize inner and outer kin, a plan without end for sons and grandsons." },
  { zh: "如不行此策，田氏復見於今，六卿必起於漢，為後嗣憂，昭昭甚明。", literal: "If this policy is not carried out, the Tian clan will appear again in our day, the Six Ministers are sure to rise in Han—grief for later heirs, clear and very plain.", idiomatic: "If this policy is not carried out, the Tian clan will appear again in our day and the Six Ministers are sure to rise in Han—grief for later heirs, clear as day." },
  { zh: "唯陛下深留聖思！", literal: "Only may Your Majesty deeply retain sage reflection!", idiomatic: "May Your Majesty reflect deeply on this!" },
  { zh: "」書奏，天子召見向，歎息悲傷其意，謂曰：「君且休矣，吾將思之。", literal: "\" When the memorial was submitted, the Son of Heaven summoned Xiang, sighed in grief at his intent, and said: \"You rest for now; I shall reflect.", idiomatic: "\" When the memorial was submitted, the emperor summoned Xiang, sighed in sympathy at his intent, and said, \"Rest for now; I shall reflect." },
  { zh: "」然終不能用其言。", literal: "\" Yet in the end he could not employ his words.", idiomatic: "\" Yet in the end he could not act on his counsel." },
  { zh: "----3　秋，關東大水。", literal: "----3 In autumn, east of the Pass suffered great flood.", idiomatic: "----3 In autumn, the region east of the Pass suffered great flooding." },
  { zh: "----4　八月，甲申，定陶共王康薨。", literal: "----4 Eighth month, on jiashen, King Kang of Dingtao Gong died.", idiomatic: "----4 In the eighth month, on jiashen, King Kang of Dingtao died." },
  { zh: "----5　是歲，徙信都王興為中山王。", literal: "----5 That year, the King of Xindu Xing was transferred to be King of Zhongshan.", idiomatic: "----5 That year, King Xing of Xindu was transferred to be King of Zhongshan." },
  { zh: "----category:資治通鑑", literal: "----category: Zizhi Tongjian", idiomatic: "----category: Zizhi Tongjian" }
];
